#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/wait.h>
#include <termios.h>
int main(){
  int m = open("/dev/ptmx", O_RDWR|O_NOCTTY);
  grantpt(m); unlockpt(m);
  const char* nm = ptsname(m);
  int s = open(nm, O_RDWR|O_NOCTTY);
  pid_t p=fork();
  if (p==0){ setsid(); printf("[child] ioctl on open pty: %s\n", ioctl(s,TIOCSCTTY,NULL)==0?"OK":strerror(errno)); 
    /* now kill master */
    _exit(0);
  } else { wait(NULL); }
  close(m);
  printf("[parent] closed master; node exists: %d\n", access(nm, F_OK)==0);
  pid_t p2=fork();
  if (p2==0){ setsid(); printf("[child2] ioctl on dead pty: %s\n", ioctl(s,TIOCSCTTY,NULL)==0?"OK":strerror(errno));
    int s2=open(nm,O_RDWR|O_NOCTTY); printf("[child2] reopen: %s\n", s2<0?strerror(errno):"OK");
    int t=open("/dev/tty",O_RDWR|O_NOCTTY); printf("[child2] open /dev/tty: %s\n", t<0?strerror(errno):"OK");
    _exit(0);
  } else { wait(NULL); }
  return 0;
}
EOF
