{"command": "cat > /workspace/src/util.c <<'EOF'
#include "dropbear.h"

void *db_malloc(size_t size) {
	void *ret;
	if (size == 0) size = 1;
	ret = malloc(size);
	if (ret == NULL) {
		dropbear_exit("Out of memory");
	}
	return ret;
}

void *db_realloc(void *ptr, size_t size) {
	void *ret;
	if (size == 0) size = 1;
	ret = realloc(ptr, size);
	if (ret == NULL) {
		dropbear_exit("Out of memory");
	}
	return ret;
}

char *db_strdup(const char *str) {
	char *ret = db_malloc(strlen(str)+1);
	strcpy(ret, str);
	return ret;
}

void db_free(void *p) {
	if (p) free(p);
}

void m_free(void *p) { db_free(p); }

char *m_strdup_a(const char *s) { return db_strdup(s); }

/* ------------------------------------------------------------------ */
/* log                                                                 */
/* ------------------------------------------------------------------ */
void dropbear_log(int prio, const char *fmt, ...) {
	char timestr[40];
	char msg[1024];
	va_list va;
	time_t now;
	struct tm *tm;
	int len;

	time(&now);
	tm = localtime(&now);
	strftime(timestr, sizeof(timestr), "%b %e %H:%M:%S", tm);

	va_start(va, fmt);
	vsnprintf(msg, sizeof(msg), fmt, va);
	va_end(va);
	/* strip trailing newlines */
	len = strlen(msg);
	while (len > 0 && (msg[len-1] == '\n' || msg[len-1] == '\r')) {
		msg[len-1] = '\0';
		len--;
	}
	fprintf(stderr, "[%d] %s %s\n", getpid(), timestr, msg);
	fflush(stderr);
}

int exit_exit_code = 1;

void dropbear_exit(const char *fmt, ...) {
	char timestr[40];
	char msg[1024];
	va_list va;
	time_t now;
	struct tm *tm;

	time(&now);
	tm = localtime(&now);
	strftime(timestr, sizeof(timestr), "%b %e %H:%M:%S", tm);
	va_start(va, fmt);
	vsnprintf(msg, sizeof(msg), fmt, va);
	va_end(va);
	fprintf(stderr, "[%d] %s Early exit: %s\n", getpid(), timestr, msg);
	fflush(stderr);
	exit(exit_exit_code);
}

/* ------------------------------------------------------------------ */
/* buffer                                                              */
/* ------------------------------------------------------------------ */
buffer *buf_new(unsigned int size) {
	buffer *ret = db_malloc(sizeof(buffer));
	if (size < 1) size = 1;
	ret->data = db_malloc(size);
	ret->size = size;
	ret->len = 0;
	ret->pos = 0;
	return ret;
}

void buf_free(buffer *buf) {
	if (buf == NULL) return;
	db_free(buf->data);
	db_free(buf);
}

void buf_resize(buffer *buf, unsigned int newsize) {
	if (newsize < buf->size) return;
	buf->data = db_realloc(buf->data, newsize);
	buf->size = newsize;
}

void buf_append(buffer *buf, const void *data, unsigned int len) {
	if (buf->size < buf->len + len) {
		unsigned int newsize = buf->len + len;
		newsize = newsize + newsize/2 + 128;
		buf_resize(buf, newsize);
	}
	memcpy(buf->data + buf->len, data, len);
	buf->len += len;
}

void buf_setlen(buffer *buf, unsigned int len) {
	if (buf->size < len) buf_resize(buf, len);
	buf->len = len;
	if (buf->pos > buf->len) buf->pos = buf->len;
}

void buf_setpos(buffer *buf, unsigned int pos) {
	if (pos > buf->len) {
		dropbear_exit("Bad buf_setpos");
	}
	buf->pos = pos;
}

void buf_checkpos(buffer *buf) {
	if (buf->pos > buf->len) {
		dropbear_exit("Bad buf_checkpos");
	}
}

void buf_incrpos(buffer *buf, unsigned int len) {
	if (buf->pos + len > buf->len) {
		dropbear_exit("Bad buf_getptr");
	}
	buf->pos += len;
}

void buf_incrwritepos(buffer *buf, unsigned int len) {
	if (buf->pos + len > buf->len) {
		dropbear_exit("Bad buf_incrwritepos");
	}
	buf->pos += len;
}

void buf_skip(buffer *buf, unsigned int len) {
	buf_incrpos(buf, len);
}

void *buf_getptr(buffer *buf, unsigned int len) {
	if (buf->pos + len > buf->len) {
		dropbear_exit("Bad buf_getptr");
	}
	return buf->data + buf->pos;
}

void buf_putbyte(buffer *buf, unsigned char val) {
	unsigned char c = val;
	buf_append(buf, &c, 1);
}

void buf_putint(buffer *buf, unsigned int val) {
	unsigned char d[4];
	d[0] = (val >> 24) & 0xff;
	d[1] = (val >> 16) & 0xff;
	d[2] = (val >> 8) & 0xff;
	d[3] = val & 0xff;
	buf_append(buf, d, 4);
}

