void buf_putbyte(buffer *buf, unsigned char val) {
	unsigned char c = val;
	buf_append(buf, &c, 1);
}

void buf_putint(buffer *buf, unsigned int val) {
	unsigned char d[4];
	d[0] = (val >> 24) & 0xff;
	d[1] = (val >> 16) & 0xff;
	d[2] = (val >> 8) & 0xff;
	d[3] = val & 0xff;
	buf_append(buf, d, 4);
}

