	buf_putstring(buf, bytes->data, bytes->len);
}

void buf_putpadding(buffer *buf, unsigned int len) {
	unsigned char *p;
	if (buf->size < buf->len + len) {
		buf_resize(buf, buf->len + len + 16);
	}
	p = buf->data + buf->len;
	rng_bytes(p, len);
	buf->len += len;
}

void buf_putmpint(buffer *buf, const BIGNUM *mp) {
	int bytes;
	unsigned char tmp[4096];
	int i;
	if (mp == NULL) {
		buf_putint(buf, 0);
		return;
	}
	bytes = BN_num_bytes(mp);
	if (bytes < 0) bytes = 0;
	if ((unsigned int)bytes >= sizeof(tmp)) {
		buf_putint(buf, 0);
		return;
	}
	BN_bn2bin(mp, tmp);
	/* strip leading zeros */
	i = 0;
	while (i < bytes-1 && tmp[i] == 0) i++;
	if (i > 0) {
		memmove(tmp, tmp+i, bytes-i);
		bytes -= i;
	}
	/* add a leading zero if the high bit is set */
	if (bytes > 0 && (tmp[0] & 0x80)) {
		unsigned char pad = 0;
		buf_putint(buf, bytes+1);
		buf_append(buf, &pad, 1);
		buf_append(buf, tmp, bytes);
	} else {
		buf_putint(buf, bytes);
		buf_append(buf, tmp, bytes);
	}
}

