	unsigned char ret;
	if (buf->pos >= buf->len) {
		dropbear_exit("Bad buf_getbyte");
	}
	ret = buf->data[buf->pos];
	buf->pos++;
	return ret;
}

unsigned int buf_getint(buffer *buf) {
	unsigned int ret;
	unsigned char *p = buf_getptr(buf, 4);
	ret = ((unsigned int)p[0] << 24) | ((unsigned int)p[1] << 16)
		| ((unsigned int)p[2] << 8) | (unsigned int)p[3];
	buf->pos += 4;
	return ret;
}

void buf_getbytes(buffer *buf, unsigned char *out, unsigned int len) {
	unsigned char *p = buf_getptr(buf, len);
	memcpy(out, p, len);
