/* ------------------------------------------------------------------ */
/* base64                                                              */
/* ------------------------------------------------------------------ */
static const char b64tab[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
static int b64val(char c) {
	int i;
	for (i = 0; i < 64; i++) if (b64tab[i] == c) return i;
	if (c == '=') return -2;
	return -1;
}

char *db_base64_encode(const unsigned char *data, unsigned long len) {
	unsigned long outlen = ((len + 2) / 3) * 4;
	char *out = db_malloc(outlen + 1);
	unsigned long i, o = 0;
	for (i = 0; i + 3 <= len; i += 3) {
		unsigned int v = (data[i] << 16) | (data[i+1] << 8) | data[i+2];
		out[o++] = b64tab[(v >> 18) & 0x3f];
		out[o++] = b64tab[(v >> 12) & 0x3f];
		out[o++] = b64tab[(v >> 6) & 0x3f];
		out[o++] = b64tab[v & 0x3f];
	}
	if (len - i == 1) {
		unsigned int v = data[i] << 16;
		out[o++] = b64tab[(v >> 18) & 0x3f];
		out[o++] = b64tab[(v >> 12) & 0x3f];
		out[o++] = '=';
		out[o++] = '=';
	} else if (len - i == 2) {
		unsigned int v = (data[i] << 16) | (data[i+1] << 8);
		out[o++] = b64tab[(v >> 18) & 0x3f];
		out[o++] = b64tab[(v >> 12) & 0x3f];
		out[o++] = b64tab[(v >> 6) & 0x3f];
		out[o++] = '=';
	}
	out[o] = '\0';
	return out;
}

int db_base64_decode(const char *in, unsigned long *outlen, unsigned char **out) {
	unsigned long len = strlen(in);
	unsigned char *buf;
	unsigned long o = 0;
	unsigned int i, v = 0, bits = 0;
	int count = 0;
	buf = db_malloc(len + 1);
	for (i = 0; i < len; i++) {
		int c = b64val(in[i]);
		if (c == -1) { db_free(buf); *out = NULL; return -1; }
		if (c == -2) { count++; continue; }
		if (count) { db_free(buf); return -1; }
		v = (v << 6) | (unsigned)c;
		bits += 6;
		if (bits >= 8) {
			bits -= 8;
			buf[o++] = (v >> bits) & 0xff;
		}
	}
	*outlen = o;
	*out = buf;
	return 0;
}

unsigned char *read_file_to_buf(const char *filename, size_t *len) {
	FILE *f;
	unsigned char *buf;
	size_t size = 0, cap = 4096;
	f = fopen(filename, "rb");
	if (f == NULL) return NULL;
	buf = db_malloc(cap);
	while (1) {
		size_t n = fread(buf + size, 1, cap - size, f);
		size += n;
		if (n == 0) break;
		if (size == cap) {
			cap *= 2;
			buf = db_realloc(buf, cap);
		}
	}
	fclose(f);
	*len = size;
	return buf;
}

void str_to_uint(const char *str, unsigned int *out) {
	unsigned long val = 0;
	char *end;
	errno = 0;
	val = strtoul(str, &end, 10);
	if (errno != 0 || end == str || *end != '\0') {
		*out = 0;
		return;
	}
	*out = (unsigned int)val;
}
