/* ------------------------------------------------------------------ */
/* chacha20 / poly1305 (OpenSSH flavour)                               */
/* ------------------------------------------------------------------ */
#define CHACHA_KEYLEN 32
#define CHACHA_NONCELEN 8
#define POLY1305_KEYLEN 32
#define POLY1305_TAGLEN 16

static const unsigned char sigma[16] = "expand 32-byte k";

static void load32_le(unsigned int *v, const unsigned char *b) {
	*v = (unsigned)b[0] | ((unsigned)b[1] << 8) | ((unsigned)b[2] << 16) | ((unsigned)b[3] << 24);
}

#define ROTL32(x,n) (((x) << (n)) | ((x) >> (32-(n))))
#define QROUND(a,b,c,d) \
	a += b; d ^= a; d = ROTL32(d,16); \
	c += d; b ^= c; b = ROTL32(b,12); \
	a += b; d ^= a; d = ROTL32(d,8); \
	c += d; b ^= c; b = ROTL32(b,7);

static void chacha_block(const unsigned int *in, unsigned int *out) {
	unsigned int x[16];
	int i;
	memcpy(x, in, sizeof(x));
	for (i = 0; i < 10; i++) {
		QROUND(x[0], x[4], x[8], x[12]);
		QROUND(x[1], x[5], x[9], x[13]);
		QROUND(x[2], x[6], x[10], x[14]);
		QROUND(x[3], x[7], x[11], x[15]);
		QROUND(x[0], x[5], x[10], x[15]);
		QROUND(x[1], x[6], x[11], x[12]);
		QROUND(x[2], x[7], x[8], x[13]);
		QROUND(x[3], x[4], x[9], x[14]);
	}
	for (i = 0; i < 16; i++) out[i] = x[i] + in[i];
}

/* chacha keystream: OpenSSH state = constants,key,counter=0,0,nonce=[0,seqno] */
static void chacha_keystream(const unsigned char *key, unsigned int seqno,
		unsigned int start_block, unsigned char *out, unsigned int len) {
	unsigned int state[16], blk[16];
	unsigned char stream[64];
	unsigned int off = 0;
	unsigned int i;
	unsigned int block = start_block;
	if (len == 0) return;
	while (off < len) {
		memcpy(state, sigma, 16);
		for (i = 0; i < 8; i++) load32_le(&state[4+i], key + i*4);
		state[12] = block;
		state[13] = 0;
		state[14] = 0;
		state[15] = seqno;
		chacha_block(state, blk);
		for (i = 0; i < 16; i++) {
			stream[i*4+0] = (blk[i]) & 0xff;
			stream[i*4+1] = (blk[i] >> 8) & 0xff;
			stream[i*4+2] = (blk[i] >> 16) & 0xff;
			stream[i*4+3] = (blk[i] >> 24) & 0xff;
		}
		{
			unsigned int n = len - off;
			if (n > 64) n = 64;
			memcpy(out + off, stream, n);
		}
		off += 64;
		block++;
	}
}

static void poly1305(const unsigned char key[32], const unsigned char *msg,
		unsigned int msglen, unsigned char tag[16]) {
	EVP_PKEY *pkey;
	EVP_MD_CTX *ctx;
	size_t outlen;
	unsigned char out[32];
	pkey = EVP_PKEY_new_raw_private_key(EVP_PKEY_POLY1305, NULL, key, POLY1305_KEYLEN);
	if (pkey == NULL) dropbear_exit("poly1305 init failure");
	ctx = EVP_MD_CTX_new();
	if (EVP_DigestSignInit(ctx, NULL, NULL, NULL, pkey) != 1) dropbear_exit("poly1305 init failure");
	if (msglen) {
		if (EVP_DigestSignUpdate(ctx, msg, msglen) != 1) dropbear_exit("poly1305 update failure");
	}
	if (EVP_DigestSignFinal(ctx, out, &outlen) != 1) dropbear_exit("poly1305 final failure");
	memcpy(tag, out, POLY1305_TAGLEN);
	EVP_MD_CTX_free(ctx);
	EVP_PKEY_free(pkey);
}

