int crypto_ctx_init(cryptctx *ctx, int cipher, int mac, int comp, int dir_out,
		const unsigned char *key, const unsigned char *iv, const unsigned char *mackey) {
	memset(ctx, 0, sizeof(*ctx));
	ctx->cipher = cipher;
	ctx->mac = mac;
	ctx->comp = comp;
	ctx->dir_out = dir_out;
	switch (cipher) {
	case CIPHER_NONE:
		ctx->blocksz = 8;
		ctx->keysize = 0;
		break;
	case CIPHER_AES128_CTR:
		ctx->blocksz = 16;
		ctx->keysize = 16;
		ctx->ctx = EVP_CIPHER_CTX_new();
		EVP_CipherInit_ex(ctx->ctx, EVP_aes_128_ctr(), NULL, key, iv, dir_out);
		break;
	case CIPHER_AES256_CTR:
		ctx->blocksz = 16;
		ctx->keysize = 32;
		ctx->ctx = EVP_CIPHER_CTX_new();
		EVP_CipherInit_ex(ctx->ctx, EVP_aes_256_ctr(), NULL, key, iv, dir_out);
		break;
	case CIPHER_CHACHA20_POLY1305:
		ctx->blocksz = 8;
		ctx->keysize = 32;
		ctx->ctx = NULL;
		memcpy(ctx->key, key, 32);
		ctx->maclen = POLY1305_TAGLEN;
		ctx->etm = 1;
		break;
	default:
		ctx->blocksz = 8;
		break;
	}
	if (cipher != CIPHER_CHACHA20_POLY1305 && cipher != CIPHER_NONE) {
		memcpy(ctx->key, key, ctx->keysize);
		memcpy(ctx->iv, iv, 16);
	}
	if (cipher == CIPHER_NONE && mac == MAC_SHA2_256) {
		ctx->maclen = 32;
		ctx->etm = 0;
	}
	if (cipher != CIPHER_CHACHA20_POLY1305) {
		if (mac == MAC_SHA2_256) {
			ctx->maclen = 32;
			ctx->etm = 0;
			memcpy(ctx->mackey, mackey, 32);
		}
	} else {
		ctx->mac = MAC_NONE;
	}
	if (comp == COMP_ZLIB) {
		ctx->zs = db_malloc(sizeof(z_stream));
		memset(ctx->zs, 0, sizeof(z_stream));
		if (dir_out) {
			deflateInit2(ctx->zs, Z_DEFAULT_COMPRESSION, Z_DEFLATED, -15, 8, Z_DEFAULT_STRATEGY);
		} else {
			inflateInit2(ctx->zs, -15);
		}
	}
	return 0;
}

void crypto_ctx_set_seqno(cryptctx *ctx, unsigned int seqno) {
	(void)ctx; (void)seqno;
	/* only used for chacha20-poly1305, handled inline */
