	if (cipher != CIPHER_CHACHA20_POLY1305 && cipher != CIPHER_NONE) {
		memcpy(ctx->key, key, ctx->keysize);
		memcpy(ctx->iv, iv, 16);
	}
	if (cipher == CIPHER_NONE && mac == MAC_SHA2_256) {
		ctx->maclen = 32;
		ctx->etm = 0;
	}
	if (cipher != CIPHER_CHACHA20_POLY1305) {
		if (mac == MAC_SHA2_256) {
			ctx->maclen = 32;
			ctx->etm = 0;
			memcpy(ctx->mackey, mackey, 32);
		}
	} else {
		ctx->mac = MAC_NONE;
	}
	if (comp == COMP_ZLIB) {
		ctx->zs = db_malloc(sizeof(z_stream));
		memset(ctx->zs, 0, sizeof(z_stream));
		if (dir_out) {
			deflateInit2(ctx->zs, Z_DEFAULT_COMPRESSION, Z_DEFLATED, -15, 8, Z_DEFAULT_STRATEGY);
		} else {
			inflateInit2(ctx->zs, -15);
		}
