	if (ctx->cipher == CIPHER_NONE) {
		memcpy(out, in, len);
		return 0;
	}
	if (ctx->cipher == CIPHER_CHACHA20_POLY1305) {
		/* handled by the packet layer */
		memcpy(out, in, len);
		return 0;
	}
	if (ctx->ctx == NULL) return -1;
	if (EVP_CipherUpdate(ctx->ctx, out, &outl, in, len) != 1) return -1;
	return outl;
}

int crypto_ctx_decrypt(cryptctx *ctx, unsigned char *out, const unsigned char *in, unsigned int len) {
	int outl = 0;
	if (len == 0) return 0;
	if (ctx->cipher == CIPHER_NONE) {
		memcpy(out, in, len);
		return 0;
	}
	if (ctx->cipher == CIPHER_CHACHA20_POLY1305) {
		memcpy(out, in, len);
		return 0;
	}
	if (ctx->ctx == NULL) return -1;
	if (EVP_CipherUpdate(ctx->ctx, out, &outl, in, len) != 1) return -1;
	return outl;
}

/* MAC over data (non-ETM) */
void crypto_ctx_mac_in(cryptctx *ctx, unsigned char *out, const unsigned char *in, unsigned int len) {
	if (ctx->mac == MAC_SHA2_256) {
		hmac_sha256_do(ctx->mackey, 32, in, len, out);
	}
}

int crypto_ctx_mac_check(cryptctx *ctx, const unsigned char *mac, const unsigned char *in, unsigned int len) {
	unsigned char expect[64];
	if (ctx->mac != MAC_SHA2_256) return 0;
	hmac_sha256_do(ctx->mackey, 32, in, len, expect);
	return memcmp(expect, mac, 32) == 0 ? 1 : 0;
}

/* helpers used by the packet layer for chachapoly */
void crypto_chacha_packet_key(const unsigned char *key, unsigned int seqno,
		unsigned char *polykey, unsigned char *lenbuf, const unsigned char *lendata,
		unsigned char *databuf, const unsigned char *data, unsigned int datalen) {
	unsigned char ks[64];
	unsigned int i;
	unsigned int totallen = datalen;
	/* keystream needed: 4 for length, then datalen */
	{
		unsigned int need = 4 + totallen;
		unsigned char *ksb = db_malloc(need);
		chacha_keystream(key, seqno, 0, ksb, need);
		memcpy(polykey, ksb, POLY1305_KEYLEN);
		for (i = 0; i < 4; i++) lenbuf[i] = lendata[i] ^ ksb[i];
		if (datalen) {
			for (i = 0; i < datalen; i++) databuf[i] = data[i] ^ ksb[4+i];
		}
		db_free(ksb);
	}
}

int crypto_poly1305_verify(const unsigned char *polykey, const unsigned char *data,
		unsigned int len, const unsigned char *tag) {
	unsigned char t[16];
	poly1305(polykey, data, len, t);
	return memcmp(t, tag, POLY1305_TAGLEN) == 0;
}

void crypto_poly1305_make(const unsigned char *polykey, const unsigned char *data,
		unsigned int len, unsigned char *tag) {
	poly1305(polykey, data, len, tag);
}

/* ssh key derivation: hash(key, hash, letter, sessionid) */
void crypto_hash_key(const unsigned char *k, unsigned int klen, const unsigned char *h,
		unsigned int hlen, char letter, const unsigned char *sessionid, unsigned int sidlen,
		unsigned char *out, unsigned int outlen) {
	EVP_MD_CTX *ctx = EVP_MD_CTX_new();
	unsigned char md[EVP_MAX_MD_SIZE];
	unsigned int mdlen = 0;
	unsigned char buf[16];
	unsigned int pos = 0;
	buf[0] = (unsigned char)letter;
	EVP_DigestInit_ex(ctx, EVP_sha256(), NULL);
	EVP_DigestUpdate(ctx, k, klen);
	EVP_DigestUpdate(ctx, h, hlen);
	EVP_DigestUpdate(ctx, buf, 1);
	EVP_DigestUpdate(ctx, sessionid, sidlen);
	EVP_DigestFinal_ex(ctx, md, &mdlen);
	EVP_MD_CTX_free(ctx);
	while (pos < outlen) {
		unsigned int n = outlen - pos;
		if (n > mdlen) n = mdlen;
		memcpy(out + pos, md, n);
		pos += n;
		if (pos < outlen) {
			ctx = EVP_MD_CTX_new();
			EVP_DigestInit_ex(ctx, EVP_sha256(), NULL);
			EVP_DigestUpdate(ctx, k, klen);
			EVP_DigestUpdate(ctx, h, hlen);
			EVP_DigestUpdate(ctx, md, mdlen);
			EVP_DigestFinal_ex(ctx, md, &mdlen);
			EVP_MD_CTX_free(ctx);
		}
	}
}
