		/* e */
		if (buf->pos + 4 > buf->len) { db_free(algname); return -1; }
		e = buf_getmpint(buf);
		if (e == NULL) { db_free(algname); return -1; }
		if (buf->pos + 4 > buf->len) { BN_free(e); db_free(algname); return -1; }
		n = buf_getmpint(buf);
		if (n == NULL) { BN_free(e); db_free(algname); return -1; }
		if (BN_num_bits(n) < MIN_RSA_KEY_BITS) {
			dropbear_log(LOG_ERR, "RSA key too short");
			BN_free(e); BN_free(n); db_free(algname);
			return -1;
		}
		{
			RSA *rsa = RSA_new();
			BIGNUM *d, *p, *q;
			d = buf_getmpint(buf);
			if (d == NULL) { RSA_free(rsa); BN_free(e); BN_free(n); db_free(algname); return -1; }
			p = buf_getmpint(buf);
			if (p == NULL) { BN_free(d); RSA_free(rsa); BN_free(e); BN_free(n); db_free(algname); return -1; }
			q = buf_getmpint(buf);
			if (q == NULL) { BN_free(p); BN_free(d); RSA_free(rsa); BN_free(e); BN_free(n); db_free(algname); return -1; }
			RSA_set0_key(rsa, (BIGNUM*)n, (BIGNUM*)e, (BIGNUM*)d);
			RSA_set0_factors(rsa, (BIGNUM*)p, (BIGNUM*)q);
			EVP_PKEY_assign_RSA(key->rsa, rsa);
			key->have_rsa = 1;
			key->type = SIGNKEY_RSA;
		}
		db_free(algname);
		return 0;
	} else if (strcmp(algname, "ssh-ed25519") == 0) {
		unsigned int privlen;
		if (buf->pos + 4 > buf->len) { db_free(algname); return -1; }
		privlen = buf_getint(buf);
		if (privlen != 64) { db_free(algname); return -1; }
		if (buf->pos + 64 > buf->len) { db_free(algname); return -1; }
		memcpy(key->ed25519_priv, buf->data + buf->pos, 64);
		buf->pos += 64;
		memcpy(key->ed25519_pub, key->ed25519_priv + 32, 32);
		key->have_ed25519 = 1;
		key->type = SIGNKEY_ED25519;
		db_free(algname);
		return 0;
	} else if (strcmp(algname, "ecdsa-sha2-nistp256") == 0) {
		unsigned int curlen, publen, privlen;
		unsigned char curve[64];
		unsigned char pub[512];
		BIGNUM *priv;
		if (buf->pos + 4 > buf->len) { db_free(algname); return -1; }
		curlen = buf_getint(buf);
		if (curlen > 64 || buf->pos + curlen > buf->len) { db_free(algname); return -1; }
		memcpy(curve, buf->data + buf->pos, curlen);
		buf->pos += curlen;
		curve[curlen] = '\0';
		if (strcmp((char*)curve, "nistp256") != 0) { db_free(algname); return -1; }
		if (buf->pos + 4 > buf->len) { db_free(algname); return -1; }
		publen = buf_getint(buf);
		if (publen != 65 || buf->pos + 65 > buf->len) { db_free(algname); return -1; }
		memcpy(pub, buf->data + buf->pos, 65);
		buf->pos += 65;
		if (buf->pos + 4 > buf->len) { db_free(algname); return -1; }
		privlen = buf_getint(buf);
		(void)privlen;
		if (buf->pos + privlen > buf->len || privlen > 64) { db_free(algname); return -1; }
		{
			unsigned char privbuf[64];
			memcpy(privbuf, buf->data + buf->pos, privlen);
			buf->pos += privlen;
			priv = BN_bin2bn(privbuf, privlen, NULL);
		}
		if (priv == NULL) { db_free(algname); return -1; }
		{
			EVP_PKEY *pk = EVP_PKEY_new();
			EC_KEY *eck = EC_KEY_new_by_curve_name(NID_X9_62_prime256v1);
			const EC_GROUP *grp = EC_KEY_get0_group(eck);
			EC_POINT *pt = EC_POINT_new(grp);
			if (EC_POINT_oct2point(grp, pt, pub, 65, NULL) != 1 ||
					EC_KEY_set_public_key(eck, pt) != 1 ||
					EC_KEY_set_private_key(eck, priv) != 1) {
				EC_POINT_free(pt); EC_KEY_free(eck); EVP_PKEY_free(pk);
				BN_free(priv); db_free(algname);
				return -1;
			}
			EC_POINT_free(pt);
			EVP_PKEY_assign_EC_KEY(pk, eck);
			key->ec = pk;
			key->have_ec = 1;
			key->type = SIGNKEY_ECDSA_NISTP256;
		}
		BN_free(priv);
		db_free(algname);
		return 0;
	}
	db_free(algname);
	return -1;
}

int signkey_load_private_file(const char *filename, sign_key *key) {
	FILE *f;
	unsigned char *data;
	size_t size = 0;
	buffer *buf;
	int ret;

	f = fopen(filename, "rb");
	if (f == NULL) {
		return -2;
	}
	data = db_malloc(KEY_FILE_MAX);
	size = fread(data, 1, KEY_FILE_MAX, f);
	fclose(f);
	buf = buf_new(size);
	memcpy(buf->data, data, size);
	buf->len = size;
	db_free(data);
	ret = signkey_load_private_buf(buf, key);
	buf_free(buf);
	return ret;
}

/* ------------------------------------------------------------------ */
/* generate keys                                                       */
/* ------------------------------------------------------------------ */
static int rsa_generate(sign_key *key, int bits) {
	EVP_PKEY_CTX *ctx = EVP_PKEY_CTX_new_id(EVP_PKEY_RSA, NULL);
	EVP_PKEY *pkey = NULL;
	if (ctx == NULL) return -1;
	if (EVP_PKEY_keygen_init(ctx) != 1) { EVP_PKEY_CTX_free(ctx); return -1; }
	{
		OSSL_PARAM params[2];
		int b = bits;
		params[0] = OSSL_PARAM_construct_int("bits", &b, sizeof(b));
		params[1] = OSSL_PARAM_construct_end();
		EVP_PKEY_CTX_set_params(ctx, params);
	}
	if (EVP_PKEY_generate(ctx, &pkey) != 1) { EVP_PKEY_CTX_free(ctx); return -1; }
	EVP_PKEY_CTX_free(ctx);
	key->rsa = pkey;
	key->have_rsa = 1;
	key->type = SIGNKEY_RSA;
	return 0;
}

static int ecdsa_generate(sign_key *key) {
	EVP_PKEY_CTX *ctx = EVP_PKEY_CTX_new_id(EVP_PKEY_EC, NULL);
	EVP_PKEY *pkey = NULL;
	if (ctx == NULL) return -1;
	EVP_PKEY_keygen_init(ctx);
	EVP_PKEY_CTX_set_ec_paramgen_curve_nid(ctx, NID_X9_62_prime256v1);
	EVP_PKEY_CTX_set_ec_param_enc(ctx, OPENSSL_EC_NAMED_CURVE);
	if (EVP_PKEY_generate(ctx, &pkey) != 1) { EVP_PKEY_CTX_free(ctx); return -1; }
	EVP_PKEY_CTX_free(ctx);
	key->ec = pkey;
	key->have_ec = 1;
	key->type = SIGNKEY_ECDSA_NISTP256;
	return 0;
}

static int ed25519_generate(sign_key *key) {
	EVP_PKEY *pkey = NULL;
	EVP_PKEY_CTX *ctx = EVP_PKEY_CTX_new_id(EVP_PKEY_ED25519, NULL);
	if (ctx == NULL) return -1;
	EVP_PKEY_keygen_init(ctx);
	if (EVP_PKEY_generate(ctx, &pkey) != 1) { EVP_PKEY_CTX_free(ctx); return -1; }
	EVP_PKEY_CTX_free(ctx);
	{
		unsigned char priv[64], pub[32];
		size_t publen = 32;
		EVP_PKEY_get_raw_public_key(pkey, pub, &publen);
		/* need the seed: extract from the private key */
		{
			unsigned char seed[32];
			size_t seedlen = 32;
			/* OpenSSL doesn't expose the seed directly; use EVP_PKEY_get_raw_private_key */
			EVP_PKEY_get_raw_private_key(pkey, seed, &seedlen);
			memcpy(priv, seed, 32);
			memcpy(priv+32, pub, 32);
			memcpy(key->ed25519_priv, priv, 64);
			memcpy(key->ed25519_pub, pub, 32);
		}
		EVP_PKEY_free(pkey);
		/* rebuild the EVP key from the seed so signing uses our copy */
		{
			EVP_PKEY *pk = EVP_PKEY_new_raw_private_key(EVP_PKEY_ED25519, NULL, key->ed25519_priv, 32);
			key->rsa = NULL;
			/* store in rsa field unused; keep in ec? use a dedicated field */
			key->ec = pk;
		}
	}
	key->have_ed25519 = 1;
	key->type = SIGNKEY_ED25519;
	return 0;
}

int signkey_generate(int type, sign_key *key) {
	switch (type) {
	case SIGNKEY_RSA: return rsa_generate(key, 2048);
	case SIGNKEY_ECDSA_NISTP256: return ecdsa_generate(key);
	case SIGNKEY_ED25519: return ed25519_generate(key);
	}
	return -1;
}

/* write the dropbear private key format */
int signkey_write_private_file(const char *filename, sign_key *key) {
	buffer *buf = buf_new(1024);
	FILE *f;
	int fd;
	char tmpname[1024];
	snprintf(tmpname, sizeof(tmpname), "%s.tmp%d", filename, getpid());

	switch (key->type) {
	case SIGNKEY_RSA: {
		const RSA *rsa = EVP_PKEY_get0_RSA(key->rsa);
		const BIGNUM *n, *e, *d, *p, *q;
		RSA_get0_key(rsa, &n, &e, &d);
		RSA_get0_factors(rsa, &p, &q);
		buf_putstring_alt(buf, "ssh-rsa");
		buf_putmpint(buf, e);
		buf_putmpint(buf, n);
		buf_putmpint(buf, d);
		buf_putmpint(buf, p);
		buf_putmpint(buf, q);
		break;
	}
	case SIGNKEY_ECDSA_NISTP256: {
		EC_KEY *eck = EVP_PKEY_get0_EC_KEY(key->ec);
		const EC_GROUP *grp = EC_KEY_get0_group(eck);
		const EC_POINT *pt = EC_KEY_get0_public_key(eck);
		const BIGNUM *priv = EC_KEY_get0_private_key(eck);
		unsigned char pub[128];
		int publen;
		publen = EC_POINT_point2oct(grp, pt, POINT_CONVERSION_UNCOMPRESSED, pub, sizeof(pub), NULL);
		buf_putstring_alt(buf, "ecdsa-sha2-nistp256");
		buf_putstring_alt(buf, "nistp256");
		buf_putstring(buf, pub, publen);
		buf_putmpint(buf, priv);
		break;
	}
	case SIGNKEY_ED25519: {
		buf_putstring_alt(buf, "ssh-ed25519");
		buf_putstring(buf, key->ed25519_priv, 64);
		break;
	}
	default:
		buf_free(buf);
		return -1;
	}

	fd = open(tmpname, O_WRONLY | O_CREAT | O_EXCL | O_TRUNC, 0600);
	if (fd < 0) {
		buf_free(buf);
		return -1;
	}
	f = fdopen(fd, "wb");
	fwrite(buf->data, 1, buf->len, f);
	fclose(f);
	if (rename(tmpname, filename) != 0) {
		buf_free(buf);
		return -1;
	}
	buf_free(buf);
	return 0;
}

int generate_hostkey(int type, const char *filename) {
	sign_key *key = signkey_new();
	int ret;
	ret = signkey_generate(type, key);
	if (ret != 0) { signkey_free(key); return -1; }
	ret = signkey_write_private_file(filename, key);
	signkey_free(key);
	return ret;
}

/* ------------------------------------------------------------------ */
/* public key blob                                                     */
/* ------------------------------------------------------------------ */
int signkey_write_pub_key(sign_key *key, buffer *out) {
	switch (key->type) {
	case SIGNKEY_RSA: {
		const RSA *rsa = EVP_PKEY_get0_RSA(key->rsa);
		const BIGNUM *n, *e, *d;
		RSA_get0_key(rsa, &n, &e, &d);
		(void)d;
		buf_putstring_alt(out, "ssh-rsa");
		buf_putmpint(out, e);
		buf_putmpint(out, n);
		break;
	}
	case SIGNKEY_ECDSA_NISTP256: {
		EC_KEY *eck = EVP_PKEY_get0_EC_KEY(key->ec);
		const EC_GROUP *grp = EC_KEY_get0_group(eck);
		const EC_POINT *pt = EC_KEY_get0_public_key(eck);
		unsigned char pub[128];
		int publen;
		publen = EC_POINT_point2oct(grp, pt, POINT_CONVERSION_UNCOMPRESSED, pub, sizeof(pub), NULL);
		buf_putstring_alt(out, "ecdsa-sha2-nistp256");
		buf_putstring_alt(out, "nistp256");
		buf_putstring(out, pub, publen);
		break;
	}
	case SIGNKEY_ED25519: {
		buf_putstring_alt(out, "ssh-ed25519");
		buf_putstring(out, key->ed25519_pub, 32);
		break;
	}
	default:
		return -1;
	}
	return 0;
}

/* parse a public key blob, return the type, and store the key parts in key */
int signkey_verify_pub_key(sign_key *key, buffer *pubbuf) {
	char *algname = NULL;
	unsigned int len;
	pubbuf->pos = 0;
	len = buf_getint(pubbuf);
	if (len > 9000 || pubbuf->pos + len > pubbuf->len) return -1;
	algname = db_malloc(len+1);
	memcpy(algname, pubbuf->data + pubbuf->pos, len);
	algname[len] = 0;
	pubbuf->pos += len;
	if (strcmp(algname, "ssh-rsa") == 0) {
		BIGNUM *e, *n;
		RSA *rsa;
		if (pubbuf->pos + 8 > pubbuf->len) { db_free(algname); return -1; }
		e = buf_getmpint(pubbuf);
		n = buf_getmpint(pubbuf);
		if (e == NULL || n == NULL) { db_free(algname); return -1; }
		rsa = RSA_new();
		RSA_set0_key(rsa, n, e, NULL);
		key->rsa = EVP_PKEY_new();
		EVP_PKEY_assign_RSA(key->rsa, rsa);
		key->have_rsa = 1;
		key->type = SIGNKEY_RSA;
	} else if (strcmp(algname, "ssh-ed25519") == 0) {
		unsigned int plen;
		if (pubbuf->pos + 4 > pubbuf->len) { db_free(algname); return -1; }
		plen = buf_getint(pubbuf);
		if (plen != 32 || pubbuf->pos + 32 > pubbuf->len) { db_free(algname); return -1; }
		memcpy(key->ed25519_pub, pubbuf->data + pubbuf->pos, 32);
		pubbuf->pos += 32;
		key->have_ed25519 = 1;
		key->type = SIGNKEY_ED25519;
	} else if (strcmp(algname, "ecdsa-sha2-nistp256") == 0 ||
			strcmp(algname, "ecdsa-sha2-nistp384") == 0 ||
			strcmp(algname, "ecdsa-sha2-nistp521") == 0) {
		unsigned int curlen, plen;
		unsigned char curve[64];
		unsigned char pub[256];
		if (pubbuf->pos + 4 > pubbuf->len) { db_free(algname); return -1; }
		curlen = buf_getint(pubbuf);
		if (curlen > 63 || pubbuf->pos + curlen > pubbuf->len) { db_free(algname); return -1; }
		memcpy(curve, pubbuf->data + pubbuf->pos, curlen);
		curve[curlen] = 0;
		pubbuf->pos += curlen;
		if (pubbuf->pos + 4 > pubbuf->len) { db_free(algname); return -1; }
		plen = buf_getint(pubbuf);
		if (plen > 200 || pubbuf->pos + plen > pubbuf->len) { db_free(algname); return -1; }
		memcpy(pub, pubbuf->data + pubbuf->pos, plen);
		pubbuf->pos += plen;
		{
			EVP_PKEY *pk = NULL;
			EC_KEY *eck = NULL;
			const EC_GROUP *grp;
			EC_POINT *pt;
			int nid;
			if (strcmp((char*)curve, "nistp256") == 0) nid = NID_X9_62_prime256v1;
			else if (strcmp((char*)curve, "nistp384") == 0) nid = NID_secp384r1;
			else if (strcmp((char*)curve, "nistp521") == 0) nid = NID_secp521r1;
			else { db_free(algname); return -1; }
			eck = EC_KEY_new_by_curve_name(nid);
			grp = EC_KEY_get0_group(eck);
			pt = EC_POINT_new(grp);
			if (EC_POINT_oct2point(grp, pt, pub, plen, NULL) != 1 ||
					EC_KEY_set_public_key(eck, pt) != 1) {
				EC_POINT_free(pt); EC_KEY_free(eck);
				db_free(algname);
				return -1;
			}
			EC_POINT_free(pt);
			pk = EVP_PKEY_new();
			EVP_PKEY_assign_EC_KEY(pk, eck);
			key->ec = pk;
			key->have_ec = 1;
			if (strcmp((char*)curve, "nistp256") == 0) key->type = SIGNKEY_ECDSA_NISTP256;
		}
	} else {
		db_free(algname);
		return -1;
	}
	db_free(algname);
	return 0;
}

/* ------------------------------------------------------------------ */
/* sign / verify                                                       */
/* ------------------------------------------------------------------ */
static int rsa_sign(sign_key *key, const unsigned char *data, unsigned int datalen, buffer *sig) {
	EVP_MD_CTX *ctx = EVP_MD_CTX_new();
	unsigned char *out = db_malloc(8192);
	size_t outlen = 8192;
	int ret;
	if (EVP_DigestSignInit(ctx, NULL, EVP_sha256(), NULL, key->rsa) != 1) {
		EVP_MD_CTX_free(ctx); db_free(out); return -1;
	}
	ret = EVP_DigestSign(ctx, out, &outlen, data, datalen);
	EVP_MD_CTX_free(ctx);
	if (ret != 1) { db_free(out); return -1; }
	buf_putstring_alt(sig, "rsa-sha2-256");
	buf_putstring(sig, out, outlen);
	db_free(out);
	return 0;
}

static int rsa_verify(sign_key *key, const unsigned char *data, unsigned int datalen, buffer *sig) {
	unsigned int len;
	unsigned char *s;
	EVP_MD_CTX *ctx = EVP_MD_CTX_new();
	int ret;
	sig->pos = 0;
	len = buf_getint(sig);
	if (len > sig->len - sig->pos) return 0;
	s = buf->data;
	(void)s;
	{
		unsigned char *sigdata = db_malloc(len+1);
		memcpy(sigdata, sig->data + sig->pos, len);
		ret = EVP_DigestVerifyInit(ctx, NULL, EVP_sha256(), NULL, key->rsa);
		if (ret != 1) { EVP_MD_CTX_free(ctx); db_free(sigdata); return 0; }
		ret = EVP_DigestVerify(ctx, sigdata, len, data, datalen);
		EVP_MD_CTX_free(ctx);
		db_free(sigdata);
	}
	return ret == 1 ? 1 : 0;
}

static int ed25519_sign(sign_key *key, const unsigned char *data, unsigned int datalen, buffer *sig) {
	EVP_MD_CTX *ctx = EVP_MD_CTX_new();
	unsigned char out[128];
	size_t outlen = sizeof(out);
	EVP_PKEY *pkey;
	int ret;
	pkey = EVP_PKEY_new_raw_private_key(EVP_PKEY_ED25519, NULL, key->ed25519_priv, 32);
	if (pkey == NULL) { EVP_MD_CTX_free(ctx); return -1; }
	if (EVP_DigestSignInit(ctx, NULL, NULL, NULL, pkey) != 1) {
		EVP_PKEY_free(pkey); EVP_MD_CTX_free(ctx); return -1;
	}
	ret = EVP_DigestSign(ctx, out, &outlen, data, datalen);
	EVP_PKEY_free(pkey);
	EVP_MD_CTX_free(ctx);
	if (ret != 1) return -1;
	buf_putstring_alt(sig, "ssh-ed25519");
	buf_putstring(sig, out, outlen);
	return 0;
}

static int ed25519_verify(sign_key *key, const unsigned char *data, unsigned int datalen, buffer *sig) {
	unsigned int len;
	EVP_PKEY *pkey;
	EVP_MD_CTX *ctx = EVP_MD_CTX_new();
	unsigned char sigdata[128];
	size_t siglen;
	int ret;
	sig->pos = 0;
	len = buf_getint(sig);
	if (len != 64 || len > sig->len - sig->pos) return 0;
	memcpy(sigdata, sig->data + sig->pos, 64);
	siglen = 64;
	pkey = EVP_PKEY_new_raw_public_key(EVP_PKEY_ED25519, NULL, key->ed25519_pub, 32);
	if (pkey == NULL) { EVP_MD_CTX_free(ctx); return 0; }
	if (EVP_DigestVerifyInit(ctx, NULL, NULL, NULL, pkey) != 1) {
		EVP_PKEY_free(pkey); EVP_MD_CTX_free(ctx); return 0;
	}
	ret = EVP_DigestVerify(ctx, sigdata, siglen, data, datalen);
	EVP_PKEY_free(pkey);
	EVP_MD_CTX_free(ctx);
	return ret == 1 ? 1 : 0;
}

/* convert SSH r||s to DER ECDSA_SIG */
static int ecdsa_ssh_to_der(const unsigned char *r, unsigned int rlen, const unsigned char *s, unsigned int slen,
		unsigned char *der, unsigned int *derlen) {
	ECDSA_SIG *sig;
	const BIGNUM *rb, *sb;
	unsigned char rbuf[128], sbuf[128];
	unsigned char *p;
	int n;
	if (rlen == 0 || rlen > 100 || slen == 0 || slen > 100) return -1;
	memset(rbuf, 0, sizeof(rbuf)); memset(sbuf, 0, sizeof(sbuf));
	memcpy(rbuf + sizeof(rbuf) - rlen, r, rlen);
	memcpy(sbuf + sizeof(sbuf) - slen, s, slen);
	rb = BN_bin2bn(rbuf, sizeof(rbuf), NULL);
	sb = BN_bin2bn(sbuf, sizeof(sbuf), NULL);
	sig = ECDSA_SIG_new();
	ECDSA_SIG_set0(sig, (BIGNUM*)rb, (BIGNUM*)sb);
	p = der;
	n = i2d_ECDSA_SIG(sig, &p);
	ECDSA_SIG_free(sig);
	if (n <= 0) return -1;
	*derlen = n;
	return 0;
}

static int ec_sign(sign_key *key, const unsigned char *data, unsigned int datalen, buffer *sig) {
	EVP_MD_CTX *ctx = EVP_MD_CTX_new();
	unsigned char der[512];
	size_t derlen = sizeof(der);
	int ret;
	ECDSA_SIG *s;
	const BIGNUM *r, *sn;
	unsigned char rbuf[128], sbuf[128];
	int rl, sl;
	if (EVP_DigestSignInit(ctx, NULL, EVP_sha256(), NULL, key->ec) != 1) {
		EVP_MD_CTX_free(ctx); return -1;
	}
	ret = EVP_DigestSign(ctx, der, &derlen, data, datalen);
	EVP_MD_CTX_free(ctx);
	if (ret != 1) return -1;
	{
		const unsigned char *p = der;
		s = d2i_ECDSA_SIG(NULL, &p, derlen);
	}
	if (s == NULL) return -1;
	ECDSA_SIG_get0(s, &r, &sn);
	rl = BN_num_bytes(r);
	sl = BN_num_bytes(sn);
	BN_bn2bin(r, rbuf);
	BN_bn2bin(sn, sbuf);
	ECDSA_SIG_free(s);
	{
		unsigned char r_rs[100], s_rs[100];
		unsigned int i;
		memset(r_rs, 0, sizeof(r_rs));
		memset(s_rs, 0, sizeof(s_rs));
		memcpy(r_rs + 32 - rl, rbuf, rl);
		memcpy(s_rs + 32 - sl, sbuf, sl);
		buf_putstring_alt(sig, "ecdsa-sha2-nistp256");
		{
			unsigned char blob[64];
			memcpy(blob, r_rs, 32);
			memcpy(blob+32, s_rs, 32);
			buf_putstring(sig, blob, 64);
		}
		(void)i;
	}
	return 0;
}

static int ec_verify(sign_key *key, const unsigned char *data, unsigned int datalen, buffer *sig) {
	unsigned int len;
	unsigned char blob[128];
	unsigned char der[256];
	unsigned int derlen;
	int ret;
	EVP_MD_CTX *ctx = EVP_MD_CTX_new();
	sig->pos = 0;
	len = buf_getint(sig);
	if (len > 128 || len > sig->len - sig->pos) return 0;
	memcpy(blob, sig->data + sig->pos, len);
	if (ecdsa_ssh_to_der(blob, len/2, blob + len/2, len - len/2, der, &derlen) != 0) {
		EVP_MD_CTX_free(ctx);
		return 0;
	}
	if (EVP_DigestVerifyInit(ctx, NULL, EVP_sha256(), NULL, key->ec) != 1) {
		EVP_MD_CTX_free(ctx); return 0;
	}
	ret = EVP_DigestVerify(ctx, der, derlen, data, datalen);
	EVP_MD_CTX_free(ctx);
	return ret == 1 ? 1 : 0;
}

int signkey_sign(sign_key *key, const unsigned char *data, unsigned int datalen, int sigalgo, buffer *sig) {
	(void)sigalgo;
	switch (key->type) {
	case SIGNKEY_RSA: return rsa_sign(key, data, datalen, sig);
	case SIGNKEY_ECDSA_NISTP256: return ec_sign(key, data, datalen, sig);
	case SIGNKEY_ED25519: return ed25519_sign(key, data, datalen, sig);
	}
	return -1;
}

int signkey_verify(sign_key *key, const unsigned char *data, unsigned int datalen, buffer *sig, int sigalgo) {
	(void)sigalgo;
	switch (key->type) {
	case SIGNKEY_RSA: return rsa_verify(key, data, datalen, sig);
	case SIGNKEY_ECDSA_NISTP256: return ec_verify(key, data, datalen, sig);
	case SIGNKEY_ED25519: return ed25519_verify(key, data, datalen, sig);
	}
	return 0;
}

int signkey_fingerprint_hash(const unsigned char *pubkey, unsigned int pubkeylen, char *out, unsigned int outsize) {
	unsigned char md[32];
	char *b64;
	unsigned int i, o;
	crypto_sha256(pubkey, pubkeylen, md);
	b64 = db_base64_encode(md, 32);
	/* strip padding */
	o = 0;
	for (i = 0; b64[i] && b64[i] != '=' && o < outsize-1; i++) out[o++] = b64[i];
	out[o] = '\0';
	db_free(b64);
	return 0;
}
