static int curve25519_kex(buffer *payload) {
	EVP_PKEY_CTX *ctx;
	EVP_PKEY *pkey = NULL;
	unsigned char pub[32], secret[64];
	size_t publen = 32, secretlen = 64;
	unsigned int elen;
	unsigned char *e;
