{"command": "cat > /workspace/src/kex.c <<'EOF'
#include "dropbear.h"

static void put_algo_list(buffer *buf, const algo_type *list) {
	char *str = algo_list_to_string(list);
	buf_putstring_alt(buf, str);
	db_free(str);
}

/* build the server's KEXINIT payload (without the msg type byte) */
buffer *svr_build_kexinit(void) {
	buffer *payload = buf_new(512);
	unsigned char cookie[16];
	int i;
	rng_bytes(cookie, 16);
	for (i = 0; i < 16; i++) buf_putbyte(payload, cookie[i]);
	{
		char *kexstr = db_strdup("sntrup761x25519-sha512,sntrup761x25519-sha512@openssh.com,mlkem768x25519-sha256,curve25519-sha256,curve25519-sha256@libssh.org,ecdh-sha2-nistp521,ecdh-sha2-nistp384,ecdh-sha2-nistp256,diffie-hellman-group14-sha256,kexguess2@matt.ucc.asn.au,kex-strict-s-v00@openssh.com");
		buf_putstring_alt(payload, kexstr);
		db_free(kexstr);
	}
	/* server host key algorithms: from the loaded hostkeys, in fixed order */
	{
		char str[512];
		str[0] = '\0';
		if (svr_hostkeys[SIGNKEY_ED25519]) {
			if (str[0]) strlcat(str, ",");
			strlcat(str, "ssh-ed25519");
		}
		if (svr_hostkeys[SIGNKEY_ECDSA_NISTP256]) {
			if (str[0]) strlcat(str, ",");
			strlcat(str, "ecdsa-sha2-nistp256");
		}
		if (svr_hostkeys[SIGNKEY_RSA]) {
			if (str[0]) strlcat(str, ",");
			strlcat(str, "rsa-sha2-256");
		}
		buf_putstring_alt(payload, str);
	}
	{
		char *cs = algo_list_to_string(sshciphers);
		buf_putstring_alt(payload, cs);
		buf_putstring_alt(payload, cs);
		db_free(cs);
	}
	{
		char *ms = algo_list_to_string(sshmacs);
		buf_putstring_alt(payload, ms);
		buf_putstring_alt(payload, ms);
		db_free(ms);
	}
	buf_putstring_alt(payload, "none");
	{
		char *cs = algo_list_to_string(sshcompress);
		buf_putstring_alt(payload, cs);
		db_free(cs);
	}
	buf_putstring_alt(payload, "");   /* languages ctos */
	buf_putstring_alt(payload, "");   /* languages stoc */
	buf_putbyte(payload, 0);          /* first_kex_follows */
	buf_putint(payload, 0);           /* reserved */
	return payload;
}

void svr_send_kexinit(void) {
	buffer *payload = svr_build_kexinit();
	if (ses.server_kexinit) buf_free(ses.server_kexinit);
	ses.server_kexinit = buf_new(payload->len);
	memcpy(ses.server_kexinit->data, payload->data, payload->len);
	ses.server_kexinit->len = payload->len;
	write_packet(payload);
	buf_free(payload);
}

void svr_send_newkeys(void) {
	buffer *payload = buf_new(16);
	write_packet(payload);
	buf_free(payload);
}

static const char *ext_sig_algs = "ssh-ed25519,sk-ssh-ed25519@openssh.com,ecdsa-sha2-nistp256,ecdsa-sha2-nistp384,ecdsa-sha2-nistp521,sk-ecdsa-sha2-nistp256@openssh.com,rsa-sha2-256";

void svr_send_extinfo(void) {
	buffer *payload = buf_new(256);
	buf_putint(payload, 1);   /* number of extensions */
	buf_putstring_alt(payload, "server-sig-algs");
	buf_putstring_alt(payload, ext_sig_algs);
	write_packet(payload);
	buf_free(payload);
}

/* parse the client's kexinit and negotiate */
static int kex_parse_client_kexinit(buffer *payload) {
	char *client_kex, *client_hostkey, *cc, *cs, *mc, *ms, *comp_c, *comp_s;
	int first_kex_follows;
	unsigned int reserved;
	buffer *s;
	payload->pos = 16;   /* skip the cookie */
	client_kex = buf_getstring(payload);
	client_hostkey = buf_getstring(payload);
	cc = buf_getstring(payload);
	cs = buf_getstring(payload);
	mc = buf_getstring(payload);
	ms = buf_getstring(payload);
	comp_c = buf_getstring(payload);
	comp_s = buf_getstring(payload);
	(void)buf_getstring(payload);
	(void)buf_getstring(payload);
	first_kex_follows = buf_getbyte(payload);
	reserved = buf_getint(payload);
	(void)reserved;

	if (strstr(client_kex, "kex-strict-c-v00@openssh.com") != NULL) ses.strict_kex = 1;
	if (strstr(client_kex, "ext-info-c") != NULL) ses.ext_info_requested = 1;

	ses.kex_algo = algo_pick(sshkex_algos, client_kex);
	ses.hostkey_algo = algo_pick(sshhostkey_algos, client_hostkey);
	ses.cipher_ctos = algo_pick(sshciphers, cc);
	ses.cipher_stoc = algo_pick(sshciphers, cs);
	ses.mac_ctos = algo_pick(sshmacs, mc);
	ses.mac_stoc = algo_pick(sshmacs, ms);
	ses.comp_ctos = algo_pick(sshcomps, comp_c);
	ses.comp_stoc = algo_pick(sshcompress, comp_s);

	db_free(client_kex); db_free(client_hostkey);
	db_free(cc); db_free(cs); db_free(mc); db_free(ms);
	db_free(comp_c); db_free(comp_s);
	(void)s;
	(void)first_kex_follows;
	return 0;
}

/* derive the keys and switch to the new cipher */
static void kex_newkeys(void) {
	unsigned char iv_c[64], iv_s[64], key_c[64], key_s[64], mac_c[64], mac_s[64];
	int cipher = ses.cipher_stoc;
	int cipher_c = ses.cipher_ctos;
	int keysize, ivsize = 16;
	int comp;

	if (ses.session_id_len == 0) {
		memcpy(ses.session_id, ses.exchange_hash, ses.exchange_hash_len);
		ses.session_id_len = ses.exchange_hash_len;
	}
	/* hash function */
	(void)cipher;
	if (cipher == CIPHER_AES256_CTR) keysize = 32;
	else if (cipher == CIPHER_AES128_CTR) keysize = 16;
	else if (cipher == CIPHER_CHACHA20_POLY1305) keysize = 32;
	else keysize = 16;

	crypto_hash_key(ses.k, ses.k_len, ses.exchange_hash, ses.exchange_hash_len, 'A', ses.session_id, ses.session_id_len, iv_c, ivsize);
	crypto_hash_key(ses.k, ses.k_len, ses.exchange_hash, ses.exchange_hash_len, 'B', ses.session_id, ses.session_id_len, iv_s, ivsize);
	crypto_hash_key(ses.k, ses.k_len, ses.exchange_hash, ses.exchange_hash_len, 'C', ses.session_id, ses.session_id_len, key_c, keysize);
	crypto_hash_key(ses.k, ses.k_len, ses.exchange_hash, ses.exchange_hash_len, 'D', ses.session_id, ses.session_id_len, key_s, keysize);
	crypto_hash_key(ses.k, ses.k_len, ses.exchange_hash, ses.exchange_hash_len, 'E', ses.session_id, ses.session_id_len, mac_c, 32);
	crypto_hash_key(ses.k, ses.k_len, ses.exchange_hash, ses.exchange_hash_len, 'F', ses.session_id, ses.session_id_len, mac_s, 32);

	comp = ses.comp_stoc;
	crypto_ctx_init(&ses.trans, cipher, MAC_SHA2_256, comp, 1, key_s, iv_s, mac_s);
	comp = ses.comp_ctos;
	crypto_ctx_init(&ses.recv, cipher_c, MAC_SHA2_256, comp, 0, key_c, iv_c, mac_c);
	ses.send_seqno = 0;
	ses.recv_seqno = 0;
	ses.have_keys = 1;
}

/* ------------------------------------------------------------------ */
/* curve25519                                                          */
/* ------------------------------------------------------------------ */
static int kex_curve25519(buffer *payload) {
	EVP_PKEY_CTX *ctx;
	EVP_PKEY *pkey = NULL;
	unsigned char pub[32], secret[64];
	size_t publen = 32, secretlen = 64;
	unsigned int elen;
	unsigned char *e;
	EVP_PKEY *peer;
	BIGNUM *bn;
	buffer kbuf;
	buffer *reply, *kspub, *sigbuf;
	unsigned char hash[64];
	unsigned int hlen = 0;
	int i;

	elen = buf_getint(payload);
	if (elen != 32 || payload->pos + 32 > payload->len) {
		return -1;
	}
	e = payload->data + payload->pos;
	payload->pos += 32;

	ctx = EVP_PKEY_CTX_new_id(EVP_PKEY_X25519, NULL);
	if (ctx == NULL) return -1;
	EVP_PKEY_keygen_init(ctx);
	if (EVP_PKEY_keygen(ctx, &pkey) != 1) { EVP_PKEY_CTX_free(ctx); return -1; }
	EVP_PKEY_CTX_free(ctx);
	EVP_PKEY_get_raw_public_key(pkey, pub, &publen);
	peer = EVP_PKEY_new_raw_public_key(EVP_PKEY_X25519, NULL, e, 32);
	{
		EVP_PKEY_CTX *dctx = EVP_PKEY_CTX_new(pkey, NULL);
		if (dctx == NULL) { EVP_PKEY_free(pkey); EVP_PKEY_free(peer); return -1; }
		if (EVP_PKEY_derive_init(dctx) != 1 || EVP_PKEY_derive_set_peer(dctx, peer) != 1 ||
				EVP_PKEY_derive(dctx, secret, &secretlen) != 1) {
			EVP_PKEY_CTX_free(dctx); EVP_PKEY_free(pkey); EVP_PKEY_free(peer);
			return -1;
		}
		EVP_PKEY_CTX_free(dctx);
	}
	EVP_PKEY_free(pkey);
	EVP_PKEY_free(peer);

	memset(&kbuf, 0, sizeof(kbuf));
	kbuf.data = db_malloc(secretlen+16);
	kbuf.size = secretlen+16;
	bn = BN_bin2bn(secret, secretlen, NULL);
	buf_putmpint(&kbuf, bn);
	BN_free(bn);

	kspub = buf_new(1024);
	signkey_write_pub_key(ses.hostkey, kspub);
	sigbuf = buf_new(2048);

	/* exchange hash = H(V_C, V_S, I_C, I_S, K_S, e, f, K) */
	{
		EVP_MD_CTX *mctx = EVP_MD_CTX_new();
		unsigned int olen = 0;
		EVP_DigestInit_ex(mctx, EVP_sha256(), NULL);
		EVP_DigestUpdate(mctx, ses.client_version, strlen(ses.client_version));
		EVP_DigestUpdate(mctx, SSH_VERSION, strlen(SSH_VERSION));
		EVP_DigestUpdate(mctx, ses.client_kexinit->data, ses.client_kexinit->len);
		EVP_DigestUpdate(mctx, ses.server_kexinit->data, ses.server_kexinit->len);
		EVP_DigestUpdate(mctx, kspub->data, kspub->len);
		EVP_DigestUpdate(mctx, e, 32);
		EVP_DigestUpdate(mctx, pub, 32);
		EVP_DigestUpdate(mctx, kbuf.data, kbuf.len);
		EVP_DigestFinal_ex(mctx, hash, &olen);
		EVP_MD_CTX_free(mctx);
		ses.exchange_hash_len = olen;
		memcpy(ses.exchange_hash, hash, olen);
	}
	signkey_sign(ses.hostkey, hash, olen, ses.hostkey_algo, sigbuf);

	reply = buf_new(4096);
	buf_putstring(reply, kspub->data, kspub->len);
	buf_putstring(reply, pub, 32);
	buf_putstring(reply, sigbuf->data, sigbuf->len);
	write_packet(reply);
	buf_free(reply);

	memcpy(ses.k, kbuf.data, kbuf.len);
	ses.k_len = kbuf.len;
	buf_free(kspub);
	buf_free(sigbuf);
	db_free(kbuf.data);
	(void)i;
	return 0;
}

/* ------------------------------------------------------------------ */
/* ECDH nistp                                                          */
/* ------------------------------------------------------------------ */
static int kex_ecdh(buffer *payload) {
	EVP_PKEY_CTX *ctx;
	EVP_PKEY *pkey = NULL;
	unsigned char pub[256], secret[256];
	size_t publen = sizeof(pub), secretlen = sizeof(secret);
	unsigned int elen;
	unsigned char *e;
	EVP_PKEY *peer;
	BIGNUM *bn;
	buffer kbuf;
	buffer *reply, *kspub, *sigbuf;
	unsigned char hash[64];
	unsigned int hlen = 0;
	int nid;
	int ret = -1;

	if (ses.kex_algo == KEX_ECDH_NISTP256) nid = NID_X9_62_prime256v1;
	else if (ses.kex_algo == KEX_ECDH_NISTP384) nid = NID_secp384r1;
	else if (ses.kex_algo == KEX_ECDH_NISTP521) nid = NID_secp521r1;
	else return -1;

	elen = buf_getint(payload);
	if (elen > 256 || payload->pos + elen > payload->len) return -1;
	e = payload->data + payload->pos;
	payload->pos += elen;

	ctx = EVP_PKEY_CTX_new_id(EVP_PKEY_EC, NULL);
	if (ctx == NULL) return -1;
	EVP_PKEY_keygen_init(ctx);
	EVP_PKEY_CTX_set_ec_paramgen_curve_nid(ctx, nid);
	if (EVP_PKEY_keygen(ctx, &pkey) != 1) { EVP_PKEY_CTX_free(ctx); return -1; }
	EVP_PKEY_CTX_free(ctx);
	{
		EC_KEY *eck = EVP_PKEY_get0_EC_KEY(pkey);
		const EC_GROUP *grp = EC_KEY_get0_group(eck);
		const EC_POINT *pt = EC_KEY_get0_public_key(eck);
		publen = EC_POINT_point2oct(grp, pt, POINT_CONVERSION_UNCOMPRESSED, pub, sizeof(pub), NULL);
	}
	peer = EVP_PKEY_new();
	{
		EC_KEY *eck = EC_KEY_new_by_curve_name(nid);
		const EC_GROUP *grp = EC_KEY_get0_group(eck);
		EC_POINT *pt = EC_POINT_new(grp);
		if (EC_POINT_oct2point(grp, pt, e, elen, NULL) != 1 || EC_KEY_set_public_key(eck, pt) != 1) {
			EC_POINT_free(pt); EC_KEY_free(eck); EVP_PKEY_free(peer);
			EVP_PKEY_free(pkey);
			return -1;
		}
		EC_POINT_free(pt);
		EVP_PKEY_assign_EC_KEY(peer, eck);
	}
	{
		EVP_PKEY_CTX *dctx = EVP_PKEY_CTX_new(pkey, NULL);
		if (dctx == NULL) { EVP_PKEY_free(pkey); EVP_PKEY_free(peer); return -1; }
		if (EVP_PKEY_derive_init(dctx) != 1 || EVP_PKEY_derive_set_peer(dctx, peer) != 1 ||
				EVP_PKEY_derive(dctx, secret, &secretlen) != 1) {
			EVP_PKEY_CTX_free(dctx); EVP_PKEY_free(pkey); EVP_PKEY_free(peer);
			return -1;
		}
		EVP_PKEY_CTX_free(dctx);
	}
	EVP_PKEY_free(pkey);
	EVP_PKEY_free(peer);

	memset(&kbuf, 0, sizeof(kbuf));
	kbuf.data = db_malloc(secretlen+16);
	kbuf.size = secretlen+16;
	bn = BN_bin2bn(secret, secretlen, NULL);
	buf_putmpint(&kbuf, bn);
	BN_free(bn);

	kspub = buf_new(1024);
	signkey_write_pub_key(ses.hostkey, kspub);
	sigbuf = buf_new(2048);

	{
		EVP_MD_CTX *mctx = EVP_MD_CTX_new();
		unsigned int olen = 0;
		EVP_DigestInit_ex(mctx, EVP_sha256(), NULL);
		EVP_DigestUpdate(mctx, ses.client_version, strlen(ses.client_version));
		EVP_DigestUpdate(mctx, SSH_VERSION, strlen(SSH_VERSION));
		EVP_DigestUpdate(mctx, ses.client_kexinit->data, ses.client_kexinit->len);
		EVP_DigestUpdate(mctx, ses.server_kexinit->data, ses.server_kexinit->len);
		EVP_DigestUpdate(mctx, kspub->data, kspub->len);
		EVP_DigestUpdate(mctx, e, elen);
		EVP_DigestUpdate(mctx, pub, publen);
		EVP_DigestUpdate(mctx, kbuf.data, kbuf.len);
		EVP_DigestFinal_ex(mctx, hash, &olen);
		EVP_MD_CTX_free(mctx);
		ses.exchange_hash_len = olen;
		memcpy(ses.exchange_hash, hash, olen);
	}
	signkey_sign(ses.hostkey, hash, olen, ses.hostkey_algo, sigbuf);

	reply = buf_new(4096);
	buf_putstring(reply, kspub->data, kspub->len);
	buf_putstring(reply, pub, publen);
	buf_putstring(reply, sigbuf->data, sigbuf->len);
	write_packet(reply);
	buf_free(reply);

	memcpy(ses.k, kbuf.data, kbuf.len);
	ses.k_len = kbuf.len;
	buf_free(kspub);
	buf_free(sigbuf);
	db_free(kbuf.data);
	(void)hlen;
	(void)ret;
	return 0;
}

/* ------------------------------------------------------------------ */
/* DH group14                                                          */
/* ------------------------------------------------------------------ */
static int kex_dh_group14(buffer *payload) {
	BIGNUM *p, *g, *e, *priv, *f, *k;
	EVP_PKEY_CTX *rngctx;
	buffer kbuf;
	buffer *reply, *kspub, *sigbuf;
	unsigned char hash[64];
	unsigned int hlen = 0;
	unsigned int elen;
	unsigned char *ebytes;
	unsigned char fbuf[512];
	int flen;

	elen = buf_getint(payload);
	if (elen > 1024 || payload->pos + elen > payload->len) return -1;
	ebytes = payload->data + payload->pos;
	payload->pos += elen;
	e = BN_bin2bn(ebytes, elen, NULL);
	if (e == NULL) return -1;

	p = BN_get_rfc3526_prime_2048(NULL);
	g = BN_new();
	BN_set_word(g, 2);

	/* random private exponent */
	priv = BN_new();
	{
		unsigned char rnd[128];
		rng_bytes(rnd, sizeof(rnd));
		BN_bin2bn(rnd, sizeof(rnd), priv);
	}
	f = BN_new();
	k = BN_new();
	BN_mod_exp(f, g, priv, p, NULL);
	BN_mod_exp(k, e, priv, p, NULL);
	(void)rngctx;
	if (BN_is_zero(k)) {
		/* reject */
		BN_free(e); BN_free(p); BN_free(g); BN_free(priv); BN_free(f); BN_free(k);
		return -1;
	}
	flen = BN_num_bytes(f);
	BN_bn2bin(f, fbuf);

	memset(&kbuf, 0, sizeof(kbuf));
	kbuf.data = db_malloc(BN_num_bytes(k)+16);
	kbuf.size = BN_num_bytes(k)+16;
	buf_putmpint(&kbuf, k);

	kspub = buf_new(1024);
	signkey_write_pub_key(ses.hostkey, kspub);
	sigbuf = buf_new(2048);

	{
		EVP_MD_CTX *mctx = EVP_MD_CTX_new();
		unsigned int olen = 0;
		EVP_DigestInit_ex(mctx, EVP_sha256(), NULL);
		EVP_DigestUpdate(mctx, ses.client_version, strlen(ses.client_version));
		EVP_DigestUpdate(mctx, SSH_VERSION, strlen(SSH_VERSION));
		EVP_DigestUpdate(mctx, ses.client_kexinit->data, ses.client_kexinit->len);
		EVP_DigestUpdate(mctx, ses.server_kexinit->data, ses.server_kexinit->len);
		EVP_DigestUpdate(mctx, kspub->data, kspub->len);
		EVP_DigestUpdate(mctx, ebytes, elen);
		EVP_DigestUpdate(mctx, fbuf, flen);
		EVP_DigestUpdate(mctx, kbuf.data, kbuf.len);
		EVP_DigestFinal_ex(mctx, hash, &olen);
		EVP_MD_CTX_free(mctx);
		ses.exchange_hash_len = olen;
		memcpy(ses.exchange_hash, hash, olen);
	}
	signkey_sign(ses.hostkey, hash, olen, ses.hostkey_algo, sigbuf);

	reply = buf_new(4096);
	buf_putstring(reply, kspub->data, kspub->len);
	buf_putstring(reply, fbuf, flen);
	buf_putstring(reply, sigbuf->data, sigbuf->len);
	write_packet(reply);
	buf_free(reply);

	memcpy(ses.k, kbuf.data, kbuf.len);
	ses.k_len = kbuf.len;
	buf_free(kspub);
	buf_free(sigbuf);
	db_free(kbuf.data);
	BN_free(e); BN_free(p); BN_free(g); BN_free(priv); BN_free(f); BN_free(k);
	return 0;
}

int kex_handle_packet(buffer *payload) {
	switch (payload->data[0]) {
	case SSH2_MSG_KEXINIT: {
		buffer *body = buf_new(payload->len);
		memcpy(body->data, payload->data+1, payload->len-1);
		body->len = payload->len-1;
		if (ses.client_kexinit) buf_free(ses.client_kexinit);
		ses.client_kexinit = buf_new(body->len);
		memcpy(ses.client_kexinit->data, body->data, body->len);
		ses.client_kexinit->len = body->len;
		kex_parse_client_kexinit(body);
		buf_free(body);
		if (ses.hostkey_algo == -1 || ses.kex_algo == -1 || ses.cipher_ctos == -1 ||
				ses.cipher_stoc == -1 || ses.mac_ctos == -1 || ses.mac_stoc == -1 ||
				ses.comp_ctos == -1 || ses.comp_stoc == -1) {
			return -1;
		}
		/* set up the hostkey */
		ses.hostkey = svr_hostkeys[ses.hostkey_algo];
		if (ses.hostkey == NULL) {
			session_finish("No matching algo hostkey", SSH2_DISCONNECT_KEY_EXCHANGE_FAILED);
		}
		svr_send_kexinit();
		ses.kex_state = 1;
		break;
	}
	case SSH2_MSG_KEX_ECDH_INIT:
	case SSH2_MSG_KEXDH_INIT: {
		int ret;
		if (ses.kex_algo == KEX_CURVE25519_SHA256 || ses.kex_algo == KEX_CURVE25519_SHA256_LIBSSH) {
			ret = kex_curve25519(payload);
		} else if (ses.kex_algo == KEX_ECDH_NISTP256 || ses.kex_algo == KEX_ECDH_NISTP384 ||
				ses.kex_algo == KEX_ECDH_NISTP521) {
			ret = kex_ecdh(payload);
		} else if (ses.kex_algo == KEX_DH_GROUP14_SHA256) {
			ret = kex_dh_group14(payload);
		} else {
			ret = -1;
		}
		if (ret != 0) {
			return -1;
		}
		svr_send_newkeys();
		kex_newkeys();
		if (ses.ext_info_requested) {
			svr_send_extinfo();
		}
		ses.kex_state = 2;
		break;
	}
	case SSH2_MSG_NEWKEYS:
		ses.kex_state = 3;
		break;
	default:
		return -1;
	}
	return 0;
}
