	if (EVP_PKEY_keygen(ctx, &pkey) != 1) { EVP_PKEY_CTX_free(ctx); return -1; }
	EVP_PKEY_CTX_free(ctx);
	{
		EC_KEY *eck = EVP_PKEY_get0_EC_KEY(pkey);
		const EC_GROUP *grp = EC_KEY_get0_group(eck);
		const EC_POINT *pt = EC_KEY_get0_public_key(eck);
		publen = EC_POINT_point2oct(grp, pt, POINT_CONVERSION_UNCOMPRESSED, pub, sizeof(pub), NULL);
	}
	peer = EVP_PKEY_new();
	{
		EC_KEY *eck = EC_KEY_new_by_curve_name(nid);
		const EC_GROUP *grp = EC_KEY_get0_group(eck);
		EC_POINT *pt = EC_POINT_new(grp);
		if (EC_POINT_oct2point(grp, pt, e, elen, NULL) != 1 || EC_KEY_set_public_key(eck, pt) != 1) {
			EC_POINT_free(pt); EC_KEY_free(eck); EVP_PKEY_free(peer);
			EVP_PKEY_free(pkey);
			return -1;
		}
		EC_POINT_free(pt);
		EVP_PKEY_assign_EC_KEY(peer, eck);
	}
	{
		EVP_PKEY_CTX *dctx = EVP_PKEY_CTX_new(pkey, NULL);
		if (dctx == NULL) { EVP_PKEY_free(pkey); EVP_PKEY_free(peer); return -1; }
		if (EVP_PKEY_derive_init(dctx) != 1 || EVP_PKEY_derive_set_peer(dctx, peer) != 1 ||
				EVP_PKEY_derive(dctx, secret, &secretlen) != 1) {
			EVP_PKEY_CTX_free(dctx); EVP_PKEY_free(pkey); EVP_PKEY_free(peer);
			return -1;
		}
		EVP_PKEY_CTX_free(dctx);
	}
	EVP_PKEY_free(pkey);
	EVP_PKEY_free(peer);

	memset(&kbuf, 0, sizeof(kbuf));
	kbuf.data = db_malloc(secretlen+16);
	kbuf.size = secretlen+16;
	bn = BN_bin2bn(secret, secretlen, NULL);
	buf_putmpint(&kbuf, bn);
	BN_free(bn);

	kspub = buf_new(1024);
	signkey_write_pub_key(ses.hostkey, kspub);
	sigbuf = buf_new(2048);

	{
		EVP_MD_CTX *mctx = EVP_MD_CTX_new();
		unsigned int olen = 0;
		EVP_DigestInit_ex(mctx, EVP_sha256(), NULL);
		EVP_DigestUpdate(mctx, ses.client_version, strlen(ses.client_version));
		EVP_DigestUpdate(mctx, SSH_VERSION, strlen(SSH_VERSION));
		EVP_DigestUpdate(mctx, ses.client_kexinit->data, ses.client_kexinit->len);
		EVP_DigestUpdate(mctx, ses.server_kexinit->data, ses.server_kexinit->len);
		EVP_DigestUpdate(mctx, kspub->data, kspub->len);
		EVP_DigestUpdate(mctx, e, elen);
		EVP_DigestUpdate(mctx, pub, publen);
		EVP_DigestUpdate(mctx, kbuf.data, kbuf.len);
		EVP_DigestFinal_ex(mctx, hash, &olen);
		EVP_MD_CTX_free(mctx);
		ses.exchange_hash_len = olen;
		memcpy(ses.exchange_hash, hash, olen);
	}
	signkey_sign(ses.hostkey, hash, olen, ses.hostkey_algo, sigbuf);

	reply = buf_new(4096);
	buf_putstring(reply, kspub->data, kspub->len);
	buf_putstring(reply, pub, publen);
	buf_putstring(reply, sigbuf->data, sigbuf->len);
	write_packet(reply);
	buf_free(reply);

	memcpy(ses.k, kbuf.data, kbuf.len);
	ses.k_len = kbuf.len;
	buf_free(kspub);
	buf_free(sigbuf);
	db_free(kbuf.data);
	(void)hlen;
	(void)ret;
