/* how many bytes we still need to read for a complete packet */
static int packet_pending_bytes(void) {
	unsigned int need;
	unsigned int plen;
	if (netbuf->len < 4) return 4 - netbuf->len;
	if (ses.have_keys && ses.recv.cipher == CIPHER_CHACHA20_POLY1305) {
