channel *get_channel(unsigned int n) {
	if (n >= DROPBEAR_CHANNEL_MAX) return NULL;
	return ses.chans[n];
}

static void send_unimpl(void) {
	buffer *payload = buf_new(16);
	buf_putbyte(payload, SSH2_MSG_UNIMPLEMENTED);
	buf_putint(payload, ses.recv_seqno-1);
	write_packet(payload);
	buf_free(payload);
}

static void send_request_failure(void) {
	buffer *payload = buf_new(8);
	buf_putbyte(payload, SSH2_MSG_REQUEST_FAILURE);
	write_packet(payload);
	buf_free(payload);
}

static void send_channel_success(channel *chan) {
	buffer *payload = buf_new(16);
	buf_putbyte(payload, SSH_MSG_CHANNEL_SUCCESS);
	buf_putint(payload, chan->extra ? chan->extra : 0);
	/* recipient channel is stored in extra */
	buf_free(payload);
}

/* ------------------------------------------------------------------ */
/* disconnect / finish                                                 */
/* ------------------------------------------------------------------ */
void session_finish(const char *reason, int reason_code) {
	if (!ses.auth_done) {
		if (ses.auth_user != NULL) {
			dropbear_log(LOG_INFO, "Exit before auth from <%s>: (user '%s', %d fails): %s",
				ses.addrstring, ses.auth_user, ses.auth_failcount, reason);
		} else {
			dropbear_log(LOG_INFO, "Exit before auth from <%s>: %s", ses.addrstring, reason);
		}
	} else {
		dropbear_log(LOG_INFO, "Exit (%s) from <%s>: %s", ses.auth_user, ses.addrstring, reason);
	}
	(void)reason_code;
	exit(0);
}

void send_disconnect(int reason, const char *desc) {
	buffer *payload = buf_new(256);
	buf_putbyte(payload, SSH2_MSG_DISCONNECT);
	buf_putint(payload, reason);
	buf_putstring_alt(payload, desc);
	buf_putstring_alt(payload, "en");
	write_packet(payload);
	buf_free(payload);
}

/* ------------------------------------------------------------------ */
/* version exchange                                                    */
/* ------------------------------------------------------------------ */
static int read_client_version(void) {
	char buf[300];
	unsigned int len = 0;
	unsigned char c;
	int state = 0;
	/* read until \r\n; skip pre-banner lines */
	while (1) {
		if (recv(ses.sock, &c, 1, 0) <= 0) return -1;
		if (c == '\n') {
			buf[len] = '\0';
			if (len > 0 && buf[len-1] == '\r') buf[len-1] = '\0';
			/* is this the version line? */
			if (strncmp(buf, "SSH-", 4) == 0) {
				if (check_remote_version(buf) == 0) {
					strlcpy(ses.client_version, buf, sizeof(ses.client_version));
					return 0;
				}
				{
					char *msg = db_malloc(strlen(buf)+64);
					sprintf(msg, "Incompatible remote version '%s'", buf);
					session_finish(msg, SSH2_DISCONNECT_PROTOCOL_VERSION_NOT_SUPPORTED);
				}
			}
			/* otherwise, treat it as a pre-banner line and keep reading */
			len = 0;
			continue;
		}
		if (len < sizeof(buf)-1) buf[len++] = c;
	}
}

