void send_disconnect(int reason, const char *desc) {
	buffer *payload = buf_new(256);
	buf_putbyte(payload, SSH2_MSG_DISCONNECT);
	buf_putint(payload, reason);
	buf_putstring_alt(payload, desc);
	buf_putstring_alt(payload, "en");
	write_packet(payload);
	buf_free(payload);
}

/* ------------------------------------------------------------------ */
/* version exchange                                                    */
/* ------------------------------------------------------------------ */
static int read_client_version(void) {
	char buf[300];
	unsigned int len = 0;
	unsigned char c;
	int state = 0;
	/* read until \r\n; skip pre-banner lines */
	while (1) {
		if (recv(ses.sock, &c, 1, 0) <= 0) return -1;
		if (c == '\n') {
			buf[len] = '\0';
			if (len > 0 && buf[len-1] == '\r') buf[len-1] = '\0';
			/* is this the version line? */
			if (strncmp(buf, "SSH-", 4) == 0) {
				if (check_remote_version(buf) == 0) {
					strlcpy(ses.client_version, buf, sizeof(ses.client_version));
					return 0;
				}
				{
					char *msg = db_malloc(strlen(buf)+64);
					sprintf(msg, "Incompatible remote version '%s'", buf);
					session_finish(msg, SSH2_DISCONNECT_PROTOCOL_VERSION_NOT_SUPPORTED);
				}
			}
			/* otherwise, treat it as a pre-banner line and keep reading */
			len = 0;
			continue;
		}
		if (len < sizeof(buf)-1) buf[len++] = c;
	}
}

int check_remote_version(const char *ident) {
	if (strncasecmp(ident, "SSH-2.", 6) == 0) return 0;
	if (strncasecmp(ident, "SSH-1.99-", 9) == 0) return 0;
	return -1;
}

