/* ------------------------------------------------------------------ */
static void send_service_accept(const char *name) {
	buffer *payload = buf_new(64);
	buf_putbyte(payload, SSH2_MSG_SERVICE_ACCEPT);
	buf_putstring_alt(payload, name);
	write_packet(payload);
	buf_free(payload);
}

