	dup2(chan->childfd, 1);
	dup2(chan->childfd, 2);
	if (chan->pty == 0 && chan->childfd_err >= 0) {
		dup2(chan->childfd_err, 2);
	}
	/* close everything else */
	{
		int i;
		for (i = 3; i < 64; i++) close(i);
	}
	if (chan->pty) {
		pty_set_owner(ses.pw->pw_uid, ses.pw->pw_gid, chan->pty_name);
		pty_change_window_size(chan, chan->term_width, chan->term_height);
	}
	/* set up the environment */
	{
		char *args[4];
		args[0] = ses.pw->pw_shell;
		if (chan->cmd) {
			args[1] = "-c";
			args[2] = chan->cmd;
			args[3] = NULL;
