#include "dropbear.h"

session_t ses;
sign_key *svr_hostkeys[DROPBEAR_MAX_SIGN_ALGOS];
char *svr_hostkey_filenames[DROPBEAR_MAX_SIGN_ALGOS];
svr_opts_t svr_opts;
int ses_ready = 0;
int exit_exit_code = 1;

void packet_init(void);
int packet_pending(void);
int packet_fill(void);
void packet_netbuf_consume(unsigned int n);
unsigned int packet_netbuf_len(void);

#define CHAN_SESS 1
#define CHAN_TCPIP 2
#define CHAN_LISTENER 3

/* ------------------------------------------------------------------ */
/* channels                                                            */
/* ------------------------------------------------------------------ */
channel *get_channel(unsigned int n) {
	if (n >= DROPBEAR_CHANNEL_MAX) return NULL;
	return ses.chans[n];
}

static channel *new_channel(void) {
	unsigned int i;
	channel *chan;
	for (i = 0; i < DROPBEAR_CHANNEL_MAX; i++) {
		if (ses.chans[i] == NULL) {
			chan = db_malloc(sizeof(channel));
			memset(chan, 0, sizeof(channel));
			chan->index = i;
			chan->rcpt = 0;
			chan->writefd = -1;
			chan->readfd = -1;
			chan->errfd = -1;
			chan->sock = -1;
			chan->pty_master = -1;
			chan->pty_slave = -1;
			ses.chans[i] = chan;
			return chan;
		}
	}
	return NULL;
}

static void free_channel(channel *chan) {
	if (chan == NULL) return;
	if (chan->index < DROPBEAR_CHANNEL_MAX) ses.chans[chan->index] = NULL;
	if (chan->writefd >= 0) close(chan->writefd);
	if (chan->readfd >= 0 && chan->readfd != chan->writefd) close(chan->readfd);
	if (chan->errfd >= 0 && chan->errfd != chan->readfd) close(chan->errfd);
	if (chan->sock >= 0) close(chan->sock);
	if (chan->pty_master >= 0) close(chan->pty_master);
	if (chan->pty_slave >= 0) close(chan->pty_slave);
	db_free(chan->hostname);
	db_free(chan->originator);
	db_free(chan->cmd);
	db_free(chan->term);
	db_free(chan->ttyname);
	db_free(chan);
}

/* ------------------------------------------------------------------ */
/* outgoing packets                                                    */
/* ------------------------------------------------------------------ */
void send_service_accept(const char *name) {
	buffer *payload = buf_new(64);
	buf_putbyte(payload, SSH2_MSG_SERVICE_ACCEPT);
	buf_putstring_alt(payload, name);
	write_packet(payload);
	buf_free(payload);
}

void send_request_failure(void) {
	buffer *payload = buf_new(8);
	buf_putbyte(payload, SSH2_MSG_REQUEST_FAILURE);
	write_packet(payload);
	buf_free(payload);
}

void send_request_success(void) {
	buffer *payload = buf_new(8);
	buf_putbyte(payload, SSH2_MSG_REQUEST_SUCCESS);
	write_packet(payload);
	buf_free(payload);
}

void send_channel_data(channel *chan, const unsigned char *data, unsigned int len) {
	buffer *payload;
	if (chan->trans_closed) return;
	if (len > chan->trans_window) len = chan->trans_window;
	if (len == 0) return;
	payload = buf_new(len + 24);
	buf_putbyte(payload, SSH_MSG_CHANNEL_DATA);
	buf_putint(payload, chan->rcpt);
	buf_putstring(payload, data, len);
	write_packet(payload);
	buf_free(payload);
	chan->trans_window -= len;
}

void send_channel_eof(channel *chan) {
	buffer *payload;
	if (chan->trans_eof) return;
	chan->trans_eof = 1;
	payload = buf_new(16);
	buf_putbyte(payload, SSH_MSG_CHANNEL_EOF);
	buf_putint(payload, chan->rcpt);
	write_packet(payload);
	buf_free(payload);
}

void send_channel_close(channel *chan) {
	buffer *payload;
	if (chan->trans_closed) return;
	chan->trans_closed = 1;
	payload = buf_new(16);
	buf_putbyte(payload, SSH_MSG_CHANNEL_CLOSE);
	buf_putint(payload, chan->rcpt);
	write_packet(payload);
	buf_free(payload);
}

void send_channel_exit_status(channel *chan, int status) {
	buffer *payload;
	if (chan->sent_exit_status) return;
	chan->sent_exit_status = 1;
	payload = buf_new(32);
	buf_putbyte(payload, SSH_MSG_CHANNEL_REQUEST);
	buf_putint(payload, chan->rcpt);
	buf_putstring_alt(payload, "exit-status");
	buf_putbyte(payload, 0);
	buf_putint(payload, status);
	write_packet(payload);
	buf_free(payload);
}

void send_channel_exit_signal(channel *chan, const char *signame, int core) {
	buffer *payload;
	payload = buf_new(64);
	buf_putbyte(payload, SSH_MSG_CHANNEL_REQUEST);
	buf_putint(payload, chan->rcpt);
	buf_putstring_alt(payload, "exit-signal");
	buf_putstring_alt(payload, signame);
	buf_putbyte(payload, 0);
	buf_putbyte(payload, core);
	buf_putstring_alt(payload, "");
	write_packet(payload);
	buf_free(payload);
}

int send_channel_open_confirmation(channel *chan, unsigned int rwindow, unsigned int rmax) {
	buffer *payload = buf_new(64);
	buf_putbyte(payload, SSH_MSG_CHANNEL_OPEN_CONFIRMATION);
	buf_putint(payload, chan->rcpt);
	buf_putint(payload, chan->index);
	buf_putint(payload, rwindow);
	buf_putint(payload, rmax);
	write_packet(payload);
	buf_free(payload);
	return 0;
}

int send_channel_open_failure(unsigned int rcpt, unsigned int reason, const char *desc, const char *lang) {
	buffer *payload = buf_new(256);
	buf_putbyte(payload, SSH_MSG_CHANNEL_OPEN_FAILURE);
	buf_putint(payload, rcpt);
	buf_putint(payload, reason);
	buf_putstring_alt(payload, desc);
	buf_putstring_alt(payload, lang ? lang : "en");
	write_packet(payload);
	buf_free(payload);
	return 0;
}

static void send_channel_window_adjust(channel *chan, unsigned int add) {
	buffer *payload = buf_new(16);
	buf_putbyte(payload, SSH_MSG_CHANNEL_WINDOW_ADJUST);
	buf_putint(payload, chan->rcpt);
	buf_putint(payload, add);
	write_packet(payload);
	buf_free(payload);
}

void send_channel_success(channel *chan) {
	buffer *payload = buf_new(16);
	buf_putbyte(payload, SSH_MSG_CHANNEL_SUCCESS);
	buf_putint(payload, chan->rcpt);
	write_packet(payload);
	buf_free(payload);
}

void send_channel_failure(channel *chan) {
	buffer *payload = buf_new(16);
	buf_putbyte(payload, SSH_MSG_CHANNEL_FAILURE);
	buf_putint(payload, chan->rcpt);
	write_packet(payload);
	buf_free(payload);
}

/* ------------------------------------------------------------------ */
/* finish                                                              */
/* ------------------------------------------------------------------ */
void session_finish(const char *reason, int reason_code) {
	if (!ses.auth_done) {
		if (ses.auth_user != NULL) {
			dropbear_log(LOG_INFO, "Exit before auth from <%s>: (user '%s', %d fails): %s",
				ses.addrstring, ses.auth_user, ses.auth_failcount, reason);
		} else {
			dropbear_log(LOG_INFO, "Exit before auth from <%s>: %s", ses.addrstring, reason);
		}
	} else {
		dropbear_log(LOG_INFO, "Exit (%s) from <%s>: %s", ses.auth_user, ses.addrstring, reason);
	}
	(void)reason_code;
	exit(0);
}

void send_disconnect(int reason, const char *desc) {
	buffer *payload = buf_new(256);
	buf_putbyte(payload, SSH2_MSG_DISCONNECT);
	buf_putint(payload, reason);
	buf_putstring_alt(payload, desc);
	buf_putstring_alt(payload, "en");
	write_packet(payload);
	buf_free(payload);
}

/* ------------------------------------------------------------------ */
/* version exchange                                                    */
/* ------------------------------------------------------------------ */
static void svr_read_client_version(void) {
	char buf[300];
	unsigned int len = 0;
	unsigned char c;
	while (1) {
		if (recv(ses.sock, &c, 1, 0) <= 0) {
			session_finish("Exited normally", 0);
		}
		if (c == '\n') {
			buf[len] = '\0';
			if (len > 0 && buf[len-1] == '\r') buf[len-1] = '\0';
			if (strncmp(buf, "SSH-", 4) == 0) {
				if (check_remote_version(buf) != 0) {
					char *msg = db_malloc(strlen(buf)+64);
					sprintf(msg, "Incompatible remote version '%s'", buf);
					session_finish(msg, SSH2_DISCONNECT_PROTOCOL_VERSION_NOT_SUPPORTED);
				}
				strlcpy(ses.client_version, buf, sizeof(ses.client_version));
				return;
			}
			len = 0;
			continue;
		}
		if (len < sizeof(buf)-1) buf[len++] = c;
	}
}

/* ------------------------------------------------------------------ */
/* signals                                                             */
/* ------------------------------------------------------------------ */
static void sigchld_handler(int sig) {
	(void)sig;
	while (waitpid(-1, NULL, WNOHANG) > 0) {}
}

void sigterm_handler(int sig) {
	(void)sig;
	dropbear_log(LOG_INFO, "Terminated by signal");
	_exit(0);
}

void svr_signal_init(void) {
	struct sigaction sa;
	memset(&sa, 0, sizeof(sa));
	sa.sa_handler = sigchld_handler;
	sigemptyset(&sa.sa_mask);
	sa.sa_flags = SA_NOCLDSTOP | SA_RESTART;
	sigaction(SIGCHLD, &sa, NULL);
	signal(SIGPIPE, SIG_IGN);
	signal(SIGHUP, SIG_IGN);
	signal(SIGQUIT, SIG_IGN);
	signal(SIGUSR1, SIG_IGN);
	signal(SIGUSR2, SIG_IGN);
	signal(SIGWINCH, SIG_IGN);
	signal(SIGINT, sigterm_handler);
	signal(SIGTERM, sigterm_handler);
}

/* ------------------------------------------------------------------ */
/* pty                                                                 */
/* ------------------------------------------------------------------ */
void pty_set_owner(uid_t uid, gid_t gid, const char *name) {
	if (chown(name, uid, gid) < 0) {
		/* ignore */
	}
	if (chmod(name, 0620) < 0) {
		/* ignore */
	}
}

void pty_change_window_size(channel *chan, int w, int h) {
	struct winsize ws;
	if (!chan->pty || chan->pty_master < 0) return;
	memset(&ws, 0, sizeof(ws));
	ws.ws_col = w;
	ws.ws_row = h;
	ws.ws_xpixel = 0;
	ws.ws_ypixel = 0;
	ioctl(chan->pty_master, TIOCSWINSZ, &ws);
}

int pty_alloc(channel *chan, const char *term, unsigned int width, unsigned int height) {
	int mfd;
	const char *name;
	mfd = open("/dev/ptmx", O_RDWR | O_NOCTTY);
	if (mfd < 0) {
		dropbear_log(LOG_ERR, "Failed opening /dev/ptmx");
		return -1;
	}
	if (grantpt(mfd) < 0 || unlockpt(mfd) < 0) {
		dropbear_log(LOG_ERR, "Failed to initialize pty");
		close(mfd);
		return -1;
	}
	name = ptsname(mfd);
	if (name == NULL) {
		close(mfd);
		return -1;
	}
	strlcpy(chan->pty_name, name, sizeof(chan->pty_name));
	chan->pty_master = mfd;
	chan->pty = 1;
	pty_set_owner(ses.pw->pw_uid, ses.pw->pw_gid, chan->pty_name);
	chan->term = db_strdup(term);
	chan->term_width = width;
	chan->term_height = height;
	return 0;
}

/* ------------------------------------------------------------------ */
/* child process                                                       */
/* ------------------------------------------------------------------ */
void svr_child_setup(channel *chan) {
	if (chan->pty) {
		setsid();
		if (ioctl(chan->pty_slave, TIOCSCTTY, NULL) < 0) {
			dropbear_log(LOG_ERR, "ioctl(TIOCSCTTY): %s", strerror(errno));
		}
		if (open(chan->pty_name, O_RDWR | O_NOCTTY) < 0) {
			dropbear_log(LOG_ERR, "%s: %s", chan->pty_name, strerror(errno));
		}
		if (open("/dev/tty", O_RDWR | O_NOCTTY) < 0) {
			dropbear_log(LOG_ERR, "open /dev/tty failed - could not set controlling tty: %s", strerror(errno));
		}
		login_record_login(0, chan->pty_name);
	}
	dup2(chan->childfd, 0);
	dup2(chan->childfd, 1);
	dup2(chan->childfd, 2);
	if (!chan->pty && chan->childfd_err >= 0) {
		dup2(chan->childfd_err, 2);
	}
	{
		int i;
		for (i = 3; i < 64; i++) close(i);
	}
	if (chan->pty) {
		pty_change_window_size(chan, chan->term_width, chan->term_height);
	}
	/* environment */
	{
		char *args[4];
		char *envp[64];
		int nenv = 0;
		envp[nenv++] = "PATH=/usr/bin:/bin:/usr/sbin:/sbin";
		envp[nenv++] = db_strdup("HOME=");
		{
			char *tmp = db_malloc(strlen(ses.pw->pw_dir)+16);
			sprintf(tmp, "HOME=%s", ses.pw->pw_dir);
			envp[nenv-1] = tmp;
		}
		{
			char *tmp = db_malloc(strlen(ses.pw->pw_name)+16);
			sprintf(tmp, "LOGNAME=%s", ses.pw->pw_name);
			envp[nenv++] = tmp;
		}
		{
			char *tmp = db_malloc(strlen(ses.pw->pw_name)+16);
			sprintf(tmp, "USER=%s", ses.pw->pw_name);
			envp[nenv++] = tmp;
		}
		{
			char *tmp = db_malloc(strlen(ses.pw->pw_shell)+16);
			sprintf(tmp, "SHELL=%s", ses.pw->pw_shell);
			envp[nenv++] = tmp;
		}
		{
			char *tmp = db_malloc(64);
			sprintf(tmp, "PATH=%s", "/usr/bin:/bin:/usr/sbin:/sbin");
			envp[nenv-4] = tmp;
		}
		if (chan->pty && chan->term) {
			char *tmp = db_malloc(strlen(chan->term)+8);
			sprintf(tmp, "TERM=%s", chan->term);
			envp[nenv++] = tmp;
		}
		envp[nenv] = NULL;
		args[0] = ses.pw->pw_shell;
		if (chan->cmd) {
			args[1] = "-c";
			args[2] = chan->cmd;
			args[3] = NULL;
		} else {
			args[1] = NULL;
		}
		chdir(ses.pw->pw_dir);
		setgid(ses.pw->pw_gid);
		initgroups(ses.pw->pw_name, ses.pw->pw_gid);
		setuid(ses.pw->pw_uid);
		execve(ses.pw->pw_shell, args, envp);
		dropbear_log(LOG_ERR, "Failed to run '%s': %s", ses.pw->pw_shell, strerror(errno));
		_exit(1);
	}
}

/* ------------------------------------------------------------------ */
/* spawn a command                                                     */
/* ------------------------------------------------------------------ */
static int spawn_command(channel *chan) {
	int pin[2], pout[2], perr[2];
	pid_t pid;
	pipe(pin); pipe(pout);
	if (chan->pty == 0) pipe(perr);
	pid = fork();
	if (pid < 0) return -1;
	if (pid == 0) {
		close(pin[1]); close(pout[0]);
		if (chan->pty == 0) close(perr[0]);
		if (chan->pty) {
			chan->childfd = chan->pty_slave;
			chan->childfd_err = -1;
		} else {
			chan->childfd = pin[0];
			chan->childfd_err = perr[1];
		}
		/* in the child, the fds to use */
		chan->childfd = chan->pty ? chan->pty_slave : pin[0];
		close(pin[1]); close(pout[0]);
		if (chan->pty == 0) close(perr[0]);
		{
			/* set up the fds */
			int i;
			int in_fd = chan->childfd;
			int out_fd = chan->pty ? chan->pty_slave : pout[1];
			int err_fd = chan->pty ? chan->pty_slave : perr[1];
			if (chan->pty) {
				setsid();
				if (ioctl(chan->pty_slave, TIOCSCTTY, NULL) < 0) {
					dropbear_log(LOG_ERR, "ioctl(TIOCSCTTY): %s", strerror(errno));
				}
				if (open(chan->pty_name, O_RDWR | O_NOCTTY) < 0) {
					dropbear_log(LOG_ERR, "%s: %s", chan->pty_name, strerror(errno));
				}
				if (open("/dev/tty", O_RDWR | O_NOCTTY) < 0) {
					dropbear_log(LOG_ERR, "open /dev/tty failed - could not set controlling tty: %s", strerror(errno));
				}
				login_record_login(0, chan->pty_name);
			}
			dup2(in_fd, 0);
			dup2(out_fd, 1);
			dup2(err_fd, 2);
			for (i = 3; i < 64; i++) close(i);
			if (chan->pty) {
				pty_change_window_size(chan, chan->term_width, chan->term_height);
			}
			/* environment */
			{
				char *args[4];
				char *envp[64];
				int nenv = 0;
				char *tmp;
				tmp = db_malloc(64);
				sprintf(tmp, "PATH=/usr/bin:/bin:/usr/sbin:/sbin");
				envp[nenv++] = tmp;
				tmp = db_malloc(strlen(ses.pw->pw_dir)+16);
				sprintf(tmp, "HOME=%s", ses.pw->pw_dir);
				envp[nenv++] = tmp;
				tmp = db_malloc(strlen(ses.pw->pw_name)+16);
				sprintf(tmp, "LOGNAME=%s", ses.pw->pw_name);
				envp[nenv++] = tmp;
				tmp = db_malloc(strlen(ses.pw->pw_name)+16);
				sprintf(tmp, "USER=%s", ses.pw->pw_name);
				envp[nenv++] = tmp;
				tmp = db_malloc(strlen(ses.pw->pw_shell)+32);
				sprintf(tmp, "SHELL=%s", ses.pw->pw_shell);
				envp[nenv++] = tmp;
				if (chan->pty && chan->term) {
					tmp = db_malloc(strlen(chan->term)+8);
					sprintf(tmp, "TERM=%s", chan->term);
					envp[nenv++] = tmp;
				}
				envp[nenv] = NULL;
				args[0] = ses.pw->pw_shell;
				if (chan->cmd) {
					args[1] = "-c";
					args[2] = chan->cmd;
					args[3] = NULL;
				} else {
					args[1] = NULL;
				}
				chdir(ses.pw->pw_dir);
				setgid(ses.pw->pw_gid);
				initgroups(ses.pw->pw_name, ses.pw->pw_gid);
				setuid(ses.pw->pw_uid);
				execve(ses.pw->pw_shell, args, envp);
				dropbear_log(LOG_ERR, "Failed to run '%s': %s", ses.pw->pw_shell, strerror(errno));
				_exit(1);
			}
		}
	}
	close(pin[0]);
	if (chan->pty == 0) close(perr[1]);
	if (chan->pty == 0) close(pout[1]);
	chan->pid = pid;
	chan->have_pid = 1;
	if (chan->pty) {
		chan->readfd = chan->pty_master;
		chan->writefd = chan->pty_master;
		chan->errfd = -1;
	} else {
		chan->readfd = pout[0];
		chan->writefd = pin[1];
		chan->errfd = perr[0];
	}
	/* close the master in the parent to match the observed behaviour */
	if (chan->pty) {
		close(chan->pty_master);
		chan->pty_master = -1;
	}
	return 0;
}

/* ------------------------------------------------------------------ */
/* tcp forwarding                                                      */
/* ------------------------------------------------------------------ */
struct fwd_entry {
	int fd;
	char *host;
	unsigned int port;
	char *orig;
	unsigned int origport;
	int used;
	struct fwd_entry *next;
};

int svr_connect_tcp(const char *host, unsigned int port, const char *orig, unsigned int origport, int *err) {
	struct addrinfo hints, *res, *ai;
	char portstr[16];
	int fd = -1;
	memset(&hints, 0, sizeof(hints));
	hints.ai_family = AF_UNSPEC;
	hints.ai_socktype = SOCK_STREAM;
	snprintf(portstr, sizeof(portstr), "%u", port);
	if (getaddrinfo(host, portstr, &hints, &res) != 0) return -1;
	for (ai = res; ai != NULL; ai = ai->ai_next) {
		fd = socket(ai->ai_family, ai->ai_socktype, ai->ai_protocol);
		if (fd < 0) continue;
		if (connect(fd, ai->ai_addr, ai->ai_addrlen) != 0) {
			close(fd);
			fd = -1;
			continue;
		}
		break;
	}
	freeaddrinfo(res);
	if (fd < 0) return -1;
	{
		int val = 1;
		setsockopt(fd, SOL_SOCKET, SO_KEEPALIVE, &val, sizeof(val));
	}
	if (orig) {
		(void)orig; (void)origport;
	}
	if (err) *err = 0;
	return fd;
}

static void svr_tcpip_open(channel *chan) {
	int fd;
	fd = svr_connect_tcp(chan->hostname, chan->port, chan->originator, chan->originator_port, NULL);
	if (fd < 0) {
		send_channel_open_failure(chan->rcpt, SSH2_OPEN_CONNECT_FAILED, "connect failed", "en");
		ses.chans[chan->index] = NULL;
		db_free(chan->hostname); db_free(chan->originator);
		db_free(chan);
		return;
	}
	chan->sock = fd;
	chan->listening = 0;
	send_channel_open_confirmation(chan, ses.recv_window, CHANNEL_MAX_PACKET);
}

void handle_channel_open(buffer *payload) {
	char *type;
	unsigned int sender, rwindow, rmax;
	type = buf_getstring(payload);
	sender = buf_getint(payload);
	rwindow = buf_getint(payload);
	rmax = buf_getint(payload);

	if (strcmp(type, "session") == 0) {
		channel *chan = new_channel();
		if (chan == NULL) {
			send_channel_open_failure(sender, SSH2_OPEN_RESOURCE_SHORTAGE, "Too many channels", "en");
			db_free(type);
			return;
		}
		chan->rcpt = sender;
		chan->type = CHAN_SESS;
		chan->trans_window = rwindow;
		chan->trans_maxpacket = rmax;
		chan->recv_window = ses.recv_window;
		chan->recv_maxpacket = CHANNEL_MAX_PACKET;
		send_channel_open_confirmation(chan, chan->recv_window, chan->recv_maxpacket);
		db_free(type);
		return;
	} else if (strcmp(type, "direct-tcpip") == 0) {
		channel *chan;
		char *host;
		unsigned int port;
		char *orig;
		unsigned int origport;
		if (svr_opts.no_localfwd) {
			send_channel_open_failure(sender, SSH2_OPEN_ADMINISTRATIVELY_PROHIBITED, "administratively prohibited", "en");
			db_free(type);
			return;
		}
		host = buf_getstring(payload);
		port = buf_getint(payload);
		orig = buf_getstring(payload);
		origport = buf_getint(payload);
		chan = new_channel();
		if (chan == NULL) {
			send_channel_open_failure(sender, SSH2_OPEN_RESOURCE_SHORTAGE, "Too many channels", "en");
			db_free(type); db_free(host); db_free(orig);
			return;
		}
		chan->rcpt = sender;
		chan->type = CHAN_TCPIP;
		chan->trans_window = rwindow;
		chan->trans_maxpacket = rmax;
		chan->recv_window = ses.recv_window;
		chan->recv_maxpacket = CHANNEL_MAX_PACKET;
		chan->hostname = host;
		chan->port = port;
		chan->originator = orig;
		chan->originator_port = origport;
		svr_tcpip_open(chan);
		db_free(type);
		return;
	} else if (strcmp(type, "forwarded-tcpip") == 0) {
		channel *chan;
		char *host;
		unsigned int port;
		char *orig;
		unsigned int origport;
		host = buf_getstring(payload);
		port = buf_getint(payload);
		orig = buf_getstring(payload);
		origport = buf_getint(payload);
		chan = new_channel();
		if (chan == NULL) {
			send_channel_open_failure(sender, SSH2_OPEN_RESOURCE_SHORTAGE, "Too many channels", "en");
			db_free(type); db_free(host); db_free(orig);
			return;
		}
		chan->rcpt = sender;
		chan->type = CHAN_TCPIP;
		chan->trans_window = rwindow;
		chan->trans_maxpacket = rmax;
		chan->recv_window = ses.recv_window;
		chan->recv_maxpacket = CHANNEL_MAX_PACKET;
		chan->hostname = host;
		chan->port = port;
		chan->originator = orig;
		chan->originator_port = origport;
		/* the connection was accepted by the listener */
		send_channel_open_confirmation(chan, chan->recv_window, chan->recv_maxpacket);
		db_free(type);
		return;
	} else if (strcmp(type, "x11") == 0) {
		send_channel_open_failure(sender, SSH2_OPEN_ADMINISTRATIVELY_PROHIBITED, "administratively prohibited", "en");
		db_free(type);
		return;
	} else if (strcmp(type, "auth-agent") == 0) {
		send_channel_open_failure(sender, SSH2_OPEN_ADMINISTRATIVELY_PROHIBITED, "administratively prohibited", "en");
		db_free(type);
		return;
	}
	/* unknown */
	send_channel_open_failure(sender, SSH2_OPEN_UNKNOWN_CHANNEL_TYPE, "unknown channel type", "en");
	db_free(type);
}

void handle_channel_data(buffer *payload) {
	unsigned int chan_num = buf_getint(payload);
	unsigned int len;
	unsigned char *data;
	channel *chan = get_channel(chan_num);
	if (chan == NULL) return;
	len = buf_getint(payload);
	if (len > payload->len - payload->pos) return;
	data = payload->data + payload->pos;
	if (chan->type == CHAN_SESS) {
		if (chan->writefd >= 0) {
			unsigned int w = len;
			unsigned int off = 0;
			while (off < w) {
				int n = write(chan->writefd, data + off, w - off);
				if (n <= 0) break;
				off += n;
			}
			chan->recv_window -= off;
			if (chan->recv_window < ses.recv_window/2) {
				send_channel_window_adjust(chan, ses.recv_window - chan->recv_window);
				chan->recv_window = ses.recv_window;
			}
		}
	} else if (chan->type == CHAN_TCPIP) {
		if (chan->sock >= 0) {
			unsigned int off = 0;
			while (off < len) {
				int n = write(chan->sock, data + off, len - off);
				if (n <= 0) break;
				off += n;
			}
			chan->recv_window -= off;
			if (chan->recv_window < ses.recv_window/2) {
				send_channel_window_adjust(chan, ses.recv_window - chan->recv_window);
				chan->recv_window = ses.recv_window;
			}
		}
	}
}

void handle_channel_extended_data(buffer *payload) {
	(void)payload;
	/* not expected from the client */
}

void handle_channel_eof(buffer *payload) {
	unsigned int chan_num = buf_getint(payload);
	channel *chan = get_channel(chan_num);
	if (chan == NULL) return;
	/* the client won't send more data */
	if (chan->writefd >= 0) {
		shutdown(chan->writefd, SHUT_WR);
	}
	chan->recv_eof = 1;
}

void handle_channel_close(buffer *payload) {
	unsigned int chan_num = buf_getint(payload);
	channel *chan = get_channel(chan_num);
	if (chan == NULL) return;
	send_channel_close(chan);
	free_channel(chan);
}

void handle_channel_window_adjust(buffer *payload) {
	unsigned int chan_num = buf_getint(payload);
	unsigned int add = buf_getint(payload);
	channel *chan = get_channel(chan_num);
	if (chan == NULL) return;
	chan->trans_window += add;
}

/* ------------------------------------------------------------------ */
/* channel requests                                                    */
/* ------------------------------------------------------------------ */
void handle_channel_request(buffer *payload) {
	unsigned int chan_num = buf_getint(payload);
	char *reqname;
	int want_reply;
	channel *chan = get_channel(chan_num);
	reqname = buf_getstring(payload);
	want_reply = buf_getbyte(payload);
	if (chan == NULL) {
		if (want_reply) send_channel_failure_msg_(NULL);
		db_free(reqname);
		return;
	}
	if (strcmp(reqname, "pty-req") == 0) {
		char *term;
		unsigned int width, height, tw, th;
		char *modes;
		unsigned int modelen;
		term = buf_getstring(payload);
		width = buf_getint(payload);
		height = buf_getint(payload);
		tw = buf_getint(payload);
		th = buf_getint(payload);
		modelen = buf_getint(payload);
		if (modelen > payload->len - payload->pos) modelen = payload->len - payload->pos;
		modes = db_malloc(modelen+1);
		memcpy(modes, payload->data + payload->pos, modelen);
		(void)modes;
		(void)tw; (void)th;
		if (chan->pty) {
			/* already allocated */
		} else {
			if (pty_alloc(chan, term, width, height) != 0) {
				if (want_reply) send_channel_failure_msg(chan);
				db_free(term);
				db_free(reqname);
				return;
			}
		}
		if (want_reply) send_channel_success(chan);
		db_free(term);
	} else if (strcmp(reqname, "shell") == 0) {
		if (chan->running) {
			if (want_reply) send_channel_failure_msg(chan);
		} else {
			chan->cmd = NULL;
			if (spawn_command(chan) != 0) {
				if (want_reply) send_channel_failure_msg(chan);
			} else {
				if (want_reply) send_channel_success(chan);
			}
		}
	} else if (strcmp(reqname, "exec") == 0) {
		char *cmd;
		if (chan->running) {
			if (want_reply) send_channel_failure_msg(chan);
		} else {
			cmd = buf_getstring(payload);
			if (svr_opts.forcecmd) {
				chan->cmd = db_strdup(svr_opts.cmd);
				db_free(cmd);
			} else {
				chan->cmd = cmd;
			}
			if (spawn_command(chan) != 0) {
				if (want_reply) send_channel_failure_msg(chan);
			} else {
				if (want_reply) send_channel_success(chan);
			}
		}
	} else if (strcmp(reqname, "env") == 0) {
		/* dropbear ignores env requests */
		if (want_reply) send_channel_success(chan);
		(void)buf_getstring(payload);
		(void)buf_getstring(payload);
	} else if (strcmp(reqname, "subsystem") == 0) {
		char *name = buf_getstring(payload);
		if (strcmp(name, "sftp") == 0) {
			chan->cmd = db_strdup(SFTP_SERVER_PATH);
			if (spawn_command(chan) != 0) {
				if (want_reply) send_channel_failure_msg(chan);
			} else {
				if (want_reply) send_channel_success(chan);
			}
		} else {
			if (want_reply) send_channel_failure_msg(chan);
		}
		db_free(name);
	} else if (strcmp(reqname, "window-change") == 0) {
		unsigned int w, h, tw, th;
		w = buf_getint(payload);
		h = buf_getint(payload);
		tw = buf_getint(payload);
		th = buf_getint(payload);
		(void)tw; (void)th;
		chan->term_width = w;
		chan->term_height = h;
		pty_change_window_size(chan, w, h);
		if (want_reply) send_channel_success(chan);
	} else if (strcmp(reqname, "signal") == 0) {
		char *signame = buf_getstring(payload);
		if (chan->have_pid) {
			int signum = signum_from_name(signame);
			if (signum > 0) {
				kill(chan->pid, signum);
			}
		}
		db_free(signame);
		if (want_reply) send_channel_success(chan);
	} else if (strcmp(reqname, "break") == 0) {
		(void)buf_getint(payload);
		if (want_reply) send_channel_success(chan);
	} else if (strcmp(reqname, "x11-req") == 0) {
		/* skip */
		if (want_reply) send_channel_failure_msg(chan);
	} else if (strcmp(reqname, "auth-agent-req@openssh.com") == 0) {
		if (want_reply) send_channel_failure_msg(chan);
	} else if (strcmp(reqname, "eow@openssh.com") == 0) {
		if (want_reply) send_channel_success(chan);
	} else {
		if (want_reply) send_channel_failure_msg(chan);
	}
	db_free(reqname);
}

/* ------------------------------------------------------------------ */
/* global requests (tcpip-forward)                                     */
/* ------------------------------------------------------------------ */
void handle_global_request(buffer *payload) {
	char *reqname = buf_getstring(payload);
	int want_reply = buf_getbyte(payload);
	if (strcmp(reqname, "tcpip-forward") == 0) {
		if (svr_opts.no_remotefwd) {
			if (want_reply) send_request_failure();
		} else {
			char *host = buf_getstring(payload);
			unsigned int port = buf_getint(payload);
			if (svr_listen_tcp(host, port, ses.addrstring, ses.remote_port) != 0) {
				if (want_reply) send_request_failure();
			} else {
				if (want_reply) send_request_success();
			}
			db_free(host);
		}
	} else if (strcmp(reqname, "cancel-tcpip-forward") == 0) {
		char *host = buf_getstring(payload);
		unsigned int port = buf_getint(payload);
		if (svr_cancel_tcpfwd(host, port) != 0) {
			if (want_reply) send_request_failure();
		} else {
			if (want_reply) send_request_success();
		}
		db_free(host);
	} else if (strcmp(reqname, "no-more-sessions@openssh.com") == 0) {
		if (want_reply) send_request_success();
	} else if (strcmp(reqname, "hostkeys-00@openssh.com") == 0) {
		if (want_reply) send_request_success();
	} else {
		if (want_reply) send_request_failure();
	}
	db_free(reqname);
}

/* ------------------------------------------------------------------ */
/* tcpip listeners                                                      */
/* ------------------------------------------------------------------ */
int svr_listen_tcp(const char *host, unsigned int port, const char *orig, unsigned int origport) {
	struct fwd_entry *fe;
	struct addrinfo hints, *res, *ai;
	char portstr[16];
	int fd = -1;
	int ret = -1;
	(void)orig; (void)origport;
	memset(&hints, 0, sizeof(hints));
	hints.ai_family = AF_UNSPEC;
	hints.ai_socktype = SOCK_STREAM;
	hints.ai_flags = AI_PASSIVE;
	if (host == NULL || host[0] == '\0') host = NULL;
	snprintf(portstr, sizeof(portstr), "%u", port);
	if (getaddrinfo(host, portstr, &hints, &res) != 0) return -1;
	for (ai = res; ai != NULL; ai = ai->ai_next) {
		int val = 1;
		fd = socket(ai->ai_family, ai->ai_socktype, ai->ai_protocol);
		if (fd < 0) continue;
		setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &val, sizeof(val));
		if (bind(fd, ai->ai_addr, ai->ai_addrlen) != 0) { close(fd); fd = -1; continue; }
		if (listen(fd, 5) != 0) { close(fd); fd = -1; continue; }
		break;
	}
	freeaddrinfo(res);
	if (fd < 0) return -1;
	fe = db_malloc(sizeof(struct fwd_entry));
	fe->fd = fd;
	fe->host = db_strdup(host ? host : "");
	fe->port = port;
	fe->orig = db_strdup(orig ? orig : "");
	fe->origport = origport;
	fe->next = ses.fwd_head;
	ses.fwd_head = fe;
	return 0;
}

int svr_cancel_tcpfwd(const char *host, unsigned int port) {
	struct fwd_entry **pp = &ses.fwd_head;
	struct fwd_entry *fe;
	while (*pp) {
		fe = *pp;
		if (fe->port == port && strcmp(fe->host, host ? host : "") == 0) {
			*pp = fe->next;
			close(fe->fd);
			db_free(fe->host); db_free(fe->orig); db_free(fe);
			return 0;
		}
		pp = &fe->next;
	}
	return -1;
}

void svr_check_tcpfwd(void) {
	struct fwd_entry *fe = ses.fwd_head;
	while (fe) {
		char buf;
		struct sockaddr_storage sa;
		socklen_t salen = sizeof(sa);
		int fd;
		/* peek: use select-based accept */
		fd = accept(fe->fd, (struct sockaddr*)&sa, &salen);
		if (fd >= 0) {
			channel *chan = new_channel();
			if (chan) {
				char ipaddr[64];
				ipaddr[0] = 0;
				if (sa.ss_family == AF_INET) {
					struct sockaddr_in *in4 = (struct sockaddr_in*)&sa;
					inet_ntop(AF_INET, &in4->sin_addr, ipaddr, sizeof(ipaddr));
				} else if (sa.ss_family == AF_INET6) {
					struct sockaddr_in6 *in6 = (struct sockaddr_in6*)&sa;
					inet_ntop(AF_INET6, &in6->sin6_addr, ipaddr, sizeof(ipaddr));
				}
				chan->rcpt = 0;
				chan->type = CHAN_TCPIP;
				chan->sock = fd;
				chan->trans_window = ses.recv_window;
				chan->trans_maxpacket = CHANNEL_MAX_PACKET;
				chan->recv_window = ses.recv_window;
				chan->recv_maxpacket = CHANNEL_MAX_PACKET;
				chan->hostname = db_strdup(fe->host);
				chan->port = fe->port;
				chan->originator = db_strdup(ipaddr);
				chan->originator_port = 0;
				{
					buffer *payload = buf_new(256);
					buf_putbyte(payload, SSH_MSG_CHANNEL_OPEN);
					buf_putstring_alt(payload, "forwarded-tcpip");
					buf_putint(payload, chan->index);
					buf_putstring(payload, fe->host, strlen(fe->host));
					buf_putint(payload, fe->port);
					buf_putstring(payload, ipaddr, strlen(ipaddr));
					buf_putint(payload, 0);
					write_packet(payload);
					buf_free(payload);
				}
			} else {
				close(fd);
			}
		} else {
			if (errno != EAGAIN && errno != EWOULDBLOCK) {
				/* error */
			}
		}
		fe = fe->next;
	}
	(void)buf;
}

void svr_tcpfwd_cleanup(void) {
	struct fwd_entry *fe = ses.fwd_head;
	while (fe) {
		struct fwd_entry *next = fe->next;
		close(fe->fd);
		db_free(fe->host); db_free(fe->orig); db_free(fe);
		fe = next;
	}
	ses.fwd_head = NULL;
}

void tcpfwd_cleanup(void) { svr_tcpfwd_cleanup(); }
void check_listen_fds(void) { svr_check_tcpfwd(); }
