/* ------------------------------------------------------------------ */
/* tcp forwarding                                                      */
/* ------------------------------------------------------------------ */
struct fwd_entry {
	int fd;
	char *host;
	unsigned int port;
	char *orig;
	unsigned int origport;
	int used;
	struct fwd_entry *next;
};

int svr_connect_tcp(const char *host, unsigned int port, const char *orig, unsigned int origport, int *err) {
	struct addrinfo hints, *res, *ai;
	char portstr[16];
	int fd = -1;
	memset(&hints, 0, sizeof(hints));
	hints.ai_family = AF_UNSPEC;
	hints.ai_socktype = SOCK_STREAM;
	snprintf(portstr, sizeof(portstr), "%u", port);
	if (getaddrinfo(host, portstr, &hints, &res) != 0) return -1;
	for (ai = res; ai != NULL; ai = ai->ai_next) {
		fd = socket(ai->ai_family, ai->ai_socktype, ai->ai_protocol);
		if (fd < 0) continue;
		if (connect(fd, ai->ai_addr, ai->ai_addrlen) != 0) {
			close(fd);
			fd = -1;
			continue;
		}
		break;
	}
	freeaddrinfo(res);
	if (fd < 0) return -1;
	{
		int val = 1;
		setsockopt(fd, SOL_SOCKET, SO_KEEPALIVE, &val, sizeof(val));
	}
	if (orig) {
		(void)orig; (void)origport;
	}
	if (err) *err = 0;
	return fd;
}

static void svr_tcpip_open(channel *chan) {
	int fd;
	fd = svr_connect_tcp(chan->hostname, chan->port, chan->originator, chan->originator_port, NULL);
	if (fd < 0) {
		send_channel_open_failure(chan->rcpt, SSH2_OPEN_CONNECT_FAILED, "connect failed", "en");
		ses.chans[chan->index] = NULL;
		db_free(chan->hostname); db_free(chan->originator);
		db_free(chan);
		return;
	}
	chan->sock = fd;
	chan->listening = 0;
	send_channel_open_confirmation(chan, ses.recv_window, CHANNEL_MAX_PACKET);
}

