				int n = read(chan->sock, buf, sizeof(buf));
				if (n <= 0) {
					send_channel_eof(chan);
					close(chan->sock);
					chan->sock = -1;
				} else {
					send_channel_data(chan, buf, n);
				}
			}
		}
	}
