/* ------------------------------------------------------------------ */
/* packet dispatch                                                     */
/* ------------------------------------------------------------------ */
static void child_reaped_all(void) {
	int i;
	int status;
	pid_t pid;
	/* check all channels for dead children */
	for (i = 0; i < DROPBEAR_CHANNEL_MAX; i++) {
		channel *chan = ses.chans[i];
		if (chan == NULL || !chan->have_pid) continue;
		pid = waitpid(chan->pid, &status, WNOHANG);
		if (pid == chan->pid) {
			chan->have_pid = 0;
			chan->exit_status = WIFEXITED(status) ? WEXITSTATUS(status) : -1;
			if (WIFSIGNALED(status)) {
				int sig = WTERMSIG(status);
				const char *signame = signame_from_num(sig);
				if (signame) send_channel_exit_signal(chan, signame, 0);
			}
			if (chan->exit_status >= 0) send_channel_exit_status(chan, chan->exit_status);
			if (chan->readfd >= 0) { close(chan->readfd); chan->readfd = -1; }
			if (chan->writefd >= 0) { close(chan->writefd); chan->writefd = -1; }
			if (chan->errfd >= 0) { close(chan->errfd); chan->errfd = -1; }
			send_channel_eof(chan);
			send_channel_close(chan);
			free_channel(chan);
		}
	}
}

