	int i;
	for (i = 0; i < DROPBEAR_CHANNEL_MAX; i++) {
		channel *chan = ses.chans[i];
		if (chan == NULL) continue;
		if (chan->type == CHAN_SESS && chan->running) {
			/* handled in the main loop */
		} else if (chan->type == CHAN_TCPIP && chan->sock >= 0) {
			/* handled in the main loop */
		}
	}
	(void)i;
}

void svr_process_packet(void) {
	buffer *payload;
	payload = read_packet();
	if (payload == NULL) {
		session_finish("Packet error", SSH2_DISCONNECT_PROTOCOL_ERROR);
	}
	switch (payload->data[0]) {
	case SSH2_MSG_DISCONNECT: {
		(void)buf_getint(payload);
		session_finish("Disconnect received", SSH2_DISCONNECT_BY_APPLICATION);
		break;
	}
	case SSH2_MSG_IGNORE:
	case SSH2_MSG_DEBUG:
		break;
	case SSH2_MSG_UNIMPLEMENTED:
		break;
	case SSH2_MSG_SERVICE_REQUEST: {
		char *name = buf_getstring(payload);
		if (strcmp(name, "ssh-userauth") == 0) {
			send_service_accept("ssh-userauth");
		} else if (strcmp(name, "ssh-connection") == 0) {
			send_service_accept("ssh-connection");
		} else {
			send_disconnect(SSH2_DISCONNECT_SERVICE_NOT_AVAILABLE, "Service not available");
			db_free(name);
			buf_free(payload);
			session_finish("Disconnect received", SSH2_DISCONNECT_BY_APPLICATION);
		}
		db_free(name);
		break;
	}
	case SSH2_MSG_USERAUTH_REQUEST: {
		svr_auth_request(payload);
		break;
	}
	case SSH2_MSG_KEXINIT:
	case SSH2_MSG_KEX_ECDH_INIT:
	case SSH2_MSG_KEXDH_INIT:
	case SSH2_MSG_NEWKEYS:
		if (kex_handle_packet(payload) != 0) {
			buf_free(payload);
			send_disconnect(SSH2_DISCONNECT_KEY_EXCHANGE_FAILED, "Key exchange failed");
			session_finish("Kex failed", SSH2_DISCONNECT_KEY_EXCHANGE_FAILED);
		}
		break;
	case SSH2_MSG_GLOBAL_REQUEST:
		handle_global_request(payload);
		break;
	case SSH2_MSG_CHANNEL_OPEN:
		handle_channel_open(payload);
		break;
	case SSH2_MSG_CHANNEL_DATA:
		handle_channel_data(payload);
		break;
	case SSH2_MSG_CHANNEL_EXTENDED_DATA:
		handle_channel_extended_data(payload);
		break;
	case SSH2_MSG_CHANNEL_EOF:
		handle_channel_eof(payload);
		break;
	case SSH2_MSG_CHANNEL_CLOSE:
		handle_channel_close(payload);
		break;
	case SSH2_MSG_CHANNEL_REQUEST:
		handle_channel_request(payload);
		break;
	case SSH2_MSG_CHANNEL_WINDOW_ADJUST:
		handle_channel_window_adjust(payload);
		break;
