/* ------------------------------------------------------------------ */
/* main loop                                                           */
/* ------------------------------------------------------------------ */
static void update_fd_set(fd_set *rset, int *maxfd) {
	int i;
	FD_ZERO(rset);
	FD_SET(ses.sock, rset);
	if (ses.sock > *maxfd) *maxfd = ses.sock;
	for (i = 0; i < DROPBEAR_CHANNEL_MAX; i++) {
		channel *chan = ses.chans[i];
		if (chan == NULL) continue;
		if (chan->type == CHAN_SESS) {
			if (chan->readfd >= 0 && chan->trans_window > 0 && chan->trans_maxpacket > 0) {
				FD_SET(chan->readfd, rset);
				if (chan->readfd > *maxfd) *maxfd = chan->readfd;
			}
			if (chan->errfd >= 0 && chan->trans_window > 0) {
				FD_SET(chan->errfd, rset);
				if (chan->errfd > *maxfd) *maxfd = chan->errfd;
			}
		} else if (chan->type == CHAN_TCPIP) {
			if (chan->sock >= 0 && chan->trans_window > 0) {
				FD_SET(chan->sock, rset);
				if (chan->sock > *maxfd) *maxfd = chan->sock;
			}
		}
	}
}

static void read_from_channel_fds(fd_set *rset) {
	int i;
	for (i = 0; i < DROPBEAR_CHANNEL_MAX; i++) {
		channel *chan = ses.chans[i];
		if (chan == NULL) continue;
		if (chan->type == CHAN_SESS) {
			if (chan->readfd >= 0 && FD_ISSET(chan->readfd, rset)) {
				unsigned char buf[CHANNEL_MAX_PACKET];
				int n = read(chan->readfd, buf, sizeof(buf));
				if (n <= 0) {
					send_channel_eof(chan);
					close(chan->readfd);
					chan->readfd = -1;
				} else {
					send_channel_data(chan, buf, n);
				}
			}
			if (chan->errfd >= 0 && FD_ISSET(chan->errfd, rset)) {
				unsigned char buf[CHANNEL_MAX_PACKET];
				int n = read(chan->errfd, buf, sizeof(buf));
				if (n <= 0) {
					close(chan->errfd);
					chan->errfd = -1;
				} else {
					/* extended data (stderr) */
					buffer *payload = buf_new(n + 24);
					buf_putbyte(payload, SSH_MSG_CHANNEL_EXTENDED_DATA);
					buf_putint(payload, chan->rcpt);
					buf_putint(payload, 1);
					buf_putstring(payload, buf, n);
					write_packet(payload);
					buf_free(payload);
					chan->trans_window -= n;
				}
			}
		} else if (chan->type == CHAN_TCPIP) {
			if (chan->sock >= 0 && FD_ISSET(chan->sock, rset)) {
				unsigned char buf[CHANNEL_MAX_PACKET];
				int n = read(chan->sock, buf, sizeof(buf));
				if (n <= 0) {
					send_channel_eof(chan);
					close(chan->sock);
					chan->sock = -1;
				} else {
					send_channel_data(chan, buf, n);
				}
			}
		}
	}
}

