void svr_session_run(void) {
	int maxfd;
	fd_set rset;
	struct timeval tv;
	int ret;
	while (1) {
		maxfd = -1;
		update_fd_set(&rset, &maxfd);
		tv.tv_sec = 1;
		tv.tv_usec = 0;
		ret = select(maxfd+1, &rset, NULL, NULL, &tv);
		if (ret < 0) {
			if (errno == EINTR) { child_reaped_all(); continue; }
			session_finish("Exited normally", 0);
		}
		if (ret == 0) {
			check_timers();
			child_reaped_all();
			continue;
		}
		if (FD_ISSET(ses.sock, &rset)) {
			int got = 0;
			while (1) {
				int r = packet_pending();
				if (r == 0) {
					svr_process_packet();
					got = 1;
					continue;
				}
				if (r < 0) {
					send_disconnect(SSH2_DISCONNECT_PROTOCOL_ERROR, "Bad packet");
					session_finish("Packet error", SSH2_DISCONNECT_PROTOCOL_ERROR);
				}
				{
					int n = packet_fill();
					if (n == 0) {
						session_finish("Exited normally", 0);
					}
					if (n < 0) {
						if (errno == EAGAIN || errno == EWOULDBLOCK) break;
						session_finish("Exited normally", 0);
					}
				}
			}
			(void)got;
		}
		read_from_channel_fds(&rset);
		check_listen_fds();
		child_reaped_all();
	}
}

