			opts.restrict = 1;
			opts.no_pty = 1; opts.no_portfwd = 1; opts.no_agentfwd = 1; opts.no_x11fwd = 1;
		} else if (strcmp(name, "environment") == 0 && val) {
			char *eq = strchr(val, '=');
			if (eq) {
				*eq = '\0';
				opts.env_name = db_strdup(val);
				opts.env_val = db_strdup(eq+1);
