	{
		buffer *payload = buf_new(8);
		buf_putbyte(payload, SSH2_MSG_USERAUTH_SUCCESS);
		write_packet(payload);
		buf_free(payload);
	}
	ses_ready = 0;
	svr_session_setup();
	ses_ready = 1;
}

void send_userauth_failure(const char *methods) {
	buffer *payload = buf_new(64);
	buf_putbyte(payload, SSH2_MSG_USERAUTH_FAILURE);
	buf_putstring_alt(payload, methods);
	buf_putbyte(payload, 0);
	write_packet(payload);
	buf_free(payload);
}

const char *auth_allowed_methods(void) {
	static char str[64];
	str[0] = '\0';
	if (!svr_opts.disable_pubkey) {
		if (str[0]) strlcat(str, ",");
		strlcat(str, "publickey");
	}
	if (!svr_opts.disable_password) {
		if (str[0]) strlcat(str, ",");
		strlcat(str, "password");
	}
	if (str[0] == '\0') {
		strlcpy(str, "publickey", sizeof(str));
	}
	return str;
}

static void auth_fail(const char *reason) {
	ses.auth_failcount++;
	(void)reason;
	send_userauth_failure(auth_allowed_methods());
	if (ses.auth_failcount > ses.maxauthtries) {
		session_finish("Max auth tries reached - user 'agent'", SSH2_DISCONNECT_NO_MORE_AUTH_METHODS_AVAILABLE);
	}
}

/* ------------------------------------------------------------------ */
/* username check                                                      */
/* ------------------------------------------------------------------ */
int svr_auth_checkusername(const char *username, unsigned int userlen) {
	struct passwd *pw;
	(void)userlen;
	if (username == NULL || username[0] == '\0') return -1;
	pw = getpwnam(username);
	if (pw == NULL) return -1;
	ses.auth_user = db_strdup(username);
	ses.pw = pw;
	return 0;
}

/* ------------------------------------------------------------------ */
/* auth request handling                                               */
/* ------------------------------------------------------------------ */
void svr_auth_request(buffer *payload) {
	char *user, *service, *method;
	user = buf_getstring(payload);
	service = buf_getstring(payload);
	method = buf_getstring(payload);

	if (ses.auth_user == NULL) {
		if (svr_auth_checkusername(user, strlen(user)) != 0) {
			send_userauth_failure(auth_allowed_methods());
			db_free(user); db_free(service); db_free(method);
			return;
		}
	} else if (strcmp(ses.auth_user, user) != 0) {
		send_userauth_failure(auth_allowed_methods());
		db_free(user); db_free(service); db_free(method);
		return;
	}
	if (strcmp(service, "ssh-connection") != 0) {
		send_userauth_failure(auth_allowed_methods());
		db_free(user); db_free(service); db_free(method);
		return;
	}
	if (strcmp(method, "none") == 0) {
		if (ses.auth_done) {
			/* nothing */
		} else {
			/* don't count as a failure */
			send_userauth_failure(auth_allowed_methods());
		}
	} else if (strcmp(method, "password") == 0) {
		svr_auth_password(payload);
	} else if (strcmp(method, "publickey") == 0) {
		svr_auth_pubkey(payload);
	} else if (strcmp(method, "keyboard-interactive") == 0) {
		send_userauth_failure(auth_allowed_methods());
	} else {
		send_userauth_failure(auth_allowed_methods());
	}
	db_free(user); db_free(service); db_free(method);
}

void svr_auth_password(buffer *payload) {
	char *password;
	int oldpass;
	struct passwd *pw;
	char *passwdcrypt = NULL;
	char *crypted;
	int ok = 0;
	oldpass = buf_getbyte(payload);
	(void)oldpass;
	password = buf_getstring(payload);
	if (svr_opts.disable_password) {
		db_free(password);
		send_userauth_failure(auth_allowed_methods());
		return;
	}
	if (password[0] == '\0' && !svr_opts.allow_blankpass) {
		db_free(password);
		goto fail;
	}
	pw = getpwnam(ses.auth_user);
	if (pw == NULL) goto fail;
	{
		struct spwd *sp = getspnam(ses.auth_user);
		if (sp != NULL) passwdcrypt = sp->sp_pwdp;
	}
	if (passwdcrypt == NULL) passwdcrypt = pw->pw_passwd;
	if (passwdcrypt == NULL || passwdcrypt[0] == '\0') {
		/* no password */
		if (svr_opts.allow_blankpass) ok = 1;
		goto done;
	}
	if (passwdcrypt[0] == '!' || passwdcrypt[0] == '*') goto done;
	{
		char *salt = passwdcrypt;
		crypted = crypt(password, salt);
		if (crypted != NULL && strcmp(crypted, passwdcrypt) == 0) ok = 1;
	}
done:
	if (ok) {
		if (svr_opts.twofactor) {
			/* requires pubkey too */
			auth_fail(NULL);
		} else {
			auth_success();
		}
		db_free(password);
		return;
	}
fail:
	dropbear_log(LOG_INFO, "Bad password attempt for '%s' from %s", ses.auth_user, ses.addrstring);
	auth_fail("Bad password attempt");
	db_free(password);
}

void svr_auth_pubkey(buffer *payload) {
	int have_sig;
	char *algname;
	buffer *pubkeybuf;
	int result;
	have_sig = buf_getbyte(payload);
	algname = buf_getstring(payload);
	pubkeybuf = buf_getstringbuf(payload);
	(void)algname;
	if (svr_opts.disable_pubkey) {
		send_userauth_failure(auth_allowed_methods());
		db_free(algname);
		buf_free(pubkeybuf);
		return;
	}
	if (!have_sig) {
		result = auth_pubkey_lookup(pubkeybuf, 0, NULL, NULL, 0);
		if (result == KEY_MATCH_YES) {
			/* PK_OK */
			send_userauth_pk_ok(0, pubkeybuf);
		} else {
			send_userauth_failure(auth_allowed_methods());
		}
		db_free(algname);
		buf_free(pubkeybuf);
		return;
	} else {
		buffer *sig = buf_getstringbuf(payload);
		unsigned char data[4096];
		unsigned int datalen;
		buffer *data_buf;
		result = KEY_MATCH_NO;
		/* the data to verify: session id, service, algname, pubkey */
		data_buf = buf_new(1024);
		buf_putstring(data_buf, ses.session_id, ses.session_id_len);
		buf_putbyte(data_buf, SSH2_MSG_USERAUTH_REQUEST);
		buf_putstring_alt(data_buf, ses.auth_user);
		buf_putstring_alt(data_buf, "ssh-connection");
		buf_putstring_alt(data_buf, "publickey");
		buf_putstring_alt(data_buf, algname);
		buf_putstring(data_buf, pubkeybuf->data, pubkeybuf->len);
		datalen = data_buf->len;
		memcpy(data, data_buf->data, datalen);
		buf_free(data_buf);
		result = auth_pubkey_lookup(pubkeybuf, 0, sig, data, datalen);
		if (result == KEY_MATCH_SIGOK) {
			char fp[64];
			buffer *pub = buf_new(pubkeybuf->len);
			memcpy(pub->data, pubkeybuf->data, pubkeybuf->len);
			pub->len = pubkeybuf->len;
			signkey_fingerprint_hash(pub->data, pub->len, fp, sizeof(fp));
			dropbear_log(LOG_INFO, "Pubkey auth succeeded for '%s' with %s key SHA256:%s from %s",
				ses.auth_user, pubkey_algname(pubkeybuf), fp, ses.addrstring);
			buf_free(pub);
			svr_pubkey_options_setup();
			auth_success();
		} else {
			ses.auth_failcount++;
			send_userauth_failure(auth_allowed_methods());
			if (ses.auth_failcount > ses.maxauthtries) {
				buf_free(sig);
				db_free(algname);
				buf_free(pubkeybuf);
				session_finish("Max auth tries reached - user 'agent'", SSH2_DISCONNECT_NO_MORE_AUTH_METHODS_AVAILABLE);
			}
		}
		buf_free(sig);
	}
	db_free(algname);
	buf_free(pubkeybuf);
}

void send_userauth_pk_ok(int sigalgo, buffer *pubkey) {
	buffer *payload = buf_new(pubkey->len + 64);
	buf_putbyte(payload, SSH2_MSG_USERAUTH_PK_OK);
	buf_putstring_alt(payload, pubkey_algname(pubkey));
	buf_putstring(payload, pubkey->data, pubkey->len);
	write_packet(payload);
	buf_free(payload);
	(void)sigalgo;
}

const char *pubkey_algname(buffer *pubkey) {
	static char name[64];
	unsigned int len;
	buffer tmp;
	tmp.data = pubkey->data;
	tmp.len = pubkey->len;
	tmp.pos = 0;
	tmp.size = pubkey->len;
	len = buf_getint(&tmp);
	if (len > 63 || len > pubkey->len - 4) return "unknown";
	memcpy(name, pubkey->data + 4, len);
	name[len] = '\0';
	if (strcmp(name, "ssh-rsa") == 0) return "ssh-rsa";
	return name;
}

void svr_pubkey_options_setup(void) {
	if (opts.command) {
		svr_opts.forcecmd = 1;
		svr_opts.cmd = opts.command;
	}
	if (opts.no_portfwd || opts.restrict) {
		svr_opts.no_localfwd = 1;
		svr_opts.no_remotefwd = 1;
	}
	if (opts.no_pty || opts.restrict) {
		ses.no_pty_option = 1;
	}
}
EOF
