actions.command:
cat > /workspace/src/auth.c <<'EOF'
#include "dropbear.h"

/* ------------------------------------------------------------------ */
/* pubkey options                                                      */
/* ------------------------------------------------------------------ */
#define MAX_OPTIONS 32
struct pubkey_opt {
	char *command;
	int no_pty;
	int no_portfwd;
	int no_agentfwd;
	int no_x11fwd;
	int no_user_rc;
	int restrict;
	char *env_name;
	char *env_val;
	char *from;
	int permit_pty;
	int permitopen_any;
};
static struct pubkey_opt opts;

void svr_pubkey_options_free(void) {
	db_free(opts.command);
	db_free(opts.env_name);
	db_free(opts.env_val);
	db_free(opts.from);
	memset(&opts, 0, sizeof(opts));
}

/* parse the options part of an authorized_keys line */
static int parse_options(const char *optstr, unsigned int len) {
	char *s = db_malloc(len+1);
	char *p;
	memcpy(s, optstr, len);
	s[len] = '\0';
	p = s;
	while (*p) {
		char *name = p;
		char *val = NULL;
		while (*p && *p != ',' && *p != '=') p++;
		if (*p == '=') {
			*p = '\0';
			p++;
			if (*p == '"') {
				p++;
				val = p;
				while (*p && *p != '"') p++;
				if (*p == '"') { *p = '\0'; p++; }
			} else {
				val = p;
				while (*p && *p != ',') p++;
				if (*p) { *p = '\0'; p++; }
			}
		} else if (*p == ',') {
			*p = '\0';
			p++;
		}
		if (strcmp(name, "command") == 0 && val) {
			opts.command = db_strdup(val);
		} else if (strcmp(name, "no-pty") == 0) {
			opts.no_pty = 1;
		} else if (strcmp(name, "no-port-forwarding") == 0) {
			opts.no_portfwd = 1;
		} else if (strcmp(name, "no-agent-forwarding") == 0) {
			opts.no_agentfwd = 1;
		} else if (strcmp(name, "no-X11-forwarding") == 0) {
			opts.no_x11fwd = 1;
		} else if (strcmp(name, "no-user-rc") == 0) {
			opts.no_user_rc = 1;
		} else if (strcmp(name, "restrict") == 0) {
			opts.restrict = 1;
			opts.no_pty = 1; opts.no_portfwd = 1; opts.no_agentfwd = 1; opts.no_x11fwd = 1;
		} else if (strcmp(name, "environment") == 0 && val) {
			char *eq = strchr(val, '=');
			if (eq) {
				*eq = '\0';
				opts.env_name = db_strdup(val);
				opts.env_val = db_strdup(eq+1);
			}
		} else if (strcmp(name, "from") == 0 && val) {
			opts.from = db_strdup(val);
		}
	}
	db_free(s);
	return 0;
}

/* ------------------------------------------------------------------ */
/* authorized_keys                                                     */
/* ------------------------------------------------------------------ */
static char *authorized_keys_filename(void) {
	char *ret;
	if (svr_opts.authdir) {
		ret = db_malloc(strlen(svr_opts.authdir) + 32);
		sprintf(ret, "%s/authorized_keys", svr_opts.authdir);
	} else {
		ret = db_malloc(strlen(ses.pw->pw_dir) + 32);
		sprintf(ret, "%s/.ssh/authorized_keys", ses.pw->pw_dir);
	}
	return ret;
}

/* check the file/dir permissions */
static int check_perm(const char *path, int isfile) {
	struct stat st;
	if (stat(path, &st) != 0) return -1;
	if (isfile) {
		if ((st.st_mode & 0777) & 0022) return -1;
		if (st.st_uid != ses.pw->pw_uid) return -1;
	} else {
		if ((st.st_mode & 0777) & 0022) return -1;
		if (st.st_uid != ses.pw->pw_uid) return -1;
	}
	return 0;
}

/* returns 1 if the key matches and (optionally) the signature verifies */
static int check_key_line(const char *line, buffer *pubkeybuf, int sigalgo, buffer *sig,
		const unsigned char *data, unsigned int datalen) {
	char *p = (char*)line;
	char *b64;
	unsigned long b64len;
	unsigned char *blob;
	buffer *keybuf;
	sign_key *key;
	int ret = 0;
	int have_sig;
	while (*p == ' ' || *p == '\t') p++;
	if (*p == '#' || *p == '\0') return 0;
	/* options? */
	if (*p != 's') {
		/* options string */
		char *q = p;
		while (*q && *q != ' ') q++;
		if (*q == '\0') return 0;
		parse_options(p, q - p);
		p = q;
		while (*p == ' ') p++;
	}
	/* keytype */
	{
		char *q = p;
		char algname[64];
		unsigned int n = 0;
		while (*q && *q != ' ') q++;
		n = q - p;
		if (n >= sizeof(algname)) return 0;
		memcpy(algname, p, n);
		algname[n] = '\0';
		p = q;
		while (*p == ' ') p++;
		(void)sigalgo;
		if (strcmp(algname, "ssh-rsa") != 0 && strcmp(algname, "ssh-ed25519") != 0 &&
				strcmp(algname, "ecdsa-sha2-nistp256") != 0 &&
				strcmp(algname, "ecdsa-sha2-nistp384") != 0 &&
				strcmp(algname, "ecdsa-sha2-nistp521") != 0 &&
				strcmp(algname, "sk-ssh-ed25519@openssh.com") != 0 &&
				strcmp(algname, "sk-ecdsa-sha2-nistp256@openssh.com") != 0) {
			return 0;
		}
	}
	have_sig = (sig != NULL);
	/* base64 blob */
	{
		char *q = p;
		while (*q && *q != ' ' && *q != '\t' && *q != '\n' && *q != '\r') q++;
		b64len = q - p;
		b64 = db_malloc(b64len+1);
		memcpy(b64, p, b64len);
		b64[b64len] = '\0';
	}
	if (db_base64_decode(b64, &b64len, &blob) != 0) {
		db_free(b64);
		return 0;
	}
	db_free(b64);
	keybuf = buf_new(b64len+1);
	memcpy(keybuf->data, blob, b64len);
	keybuf->len = b64len;
	key = signkey_new();
	if (signkey_verify_pub_key(key, keybuf) != 0) {
		buf_free(keybuf); signkey_free(key); db_free(blob);
		return 0;
	}
	buf_free(keybuf);
	/* compare with the offered key */
	{
		buffer *offered = buf_new(pubkeybuf->len+1);
		buffer *mine = buf_new(512);
		int match;
		signkey_write_pub_key(key, mine);
		offered->len = pubkeybuf->len;
		memcpy(offered->data, pubkeybuf->data, pubkeybuf->len);
		offered->pos = 0;
		match = (offered->len == mine->len && memcmp(offered->data, mine->data, mine->len) == 0);
		buf_free(offered);
		buf_free(mine);
		if (!match) {
			signkey_free(key);
			db_free(blob);
			return 0;
		}
	}
	if (have_sig) {
		ret = signkey_verify(key, data, datalen, sig, sigalgo);
	} else {
		ret = 1;
	}
	signkey_free(key);
	db_free(blob);
	return ret;
}

/* result codes */
#define KEY_MATCH_NO 0
#define KEY_MATCH_YES 1
#define KEY_MATCH_SIGOK 2
#define KEY_MATCH_SIGFAIL 3

static int auth_pubkey_lookup(buffer *pubkeybuf, int sigalgo, buffer *sig,
		const unsigned char *data, unsigned int datalen) {
	char *filename = authorized_keys_filename();
	FILE *f;
	char line[8192];
	int found = 0;
	int result = KEY_MATCH_NO;
	if (check_perm(filename, 1) != 0) {
		db_free(filename);
		return KEY_MATCH_NO;
	}
	f = fopen(filename, "rb");
	db_free(filename);
	if (f == NULL) return KEY_MATCH_NO;
	while (fgets(line, sizeof(line), f) != NULL) {
		int r;
		svr_pubkey_options_free();
		memset(&opts, 0, sizeof(opts));
		r = check_key_line(line, pubkeybuf, sigalgo, sig, data, datalen);
		if (r > 0) {
			found = 1;
			result = have_sig_result(sig) ? KEY_MATCH_SIGOK : KEY_MATCH_YES;
			if (!have_sig_result(sig) && sig) result = KEY_MATCH_SIGFAIL;
			break;
		}
	}
	svr_pubkey_options_free();
	fclose(f);
	(void)found;
	return result;
}

