#define DEFAULT_ECDSA_KEY "/etc/dropbear/dropbear_ecdsa_host_key"
#define DEFAULT_ED25519_KEY "/etc/dropbear/dropbear_ed25519_host_key"

static char *listen_addrs[MAX_LISTEN_PORTS][2];
