/* ------------------------------------------------------------------ */
static void usage(void) {
	printf("Dropbear server v%s https://matt.ucc.asn.au/dropbear/dropbear.html\n", DROPBEAR_VERSION);
	printf("Usage: %s [options]\n", progname);
	printf("-b bannerfile	Display the contents of bannerfile before user login\n");
	printf("		(default: none)\n");
	printf("-r keyfile      Specify hostkeys (repeatable)\n");
	printf("		defaults: \n");
	printf("		- rsa %s\n", DEFAULT_RSA_KEY);
