	printf("-D		Directory containing authorized_keys file\n");
	printf("-R		Create hostkeys as required\n");
	printf("-F		Don't fork into background\n");
	printf("-e		Pass on server process environment to child process\n");
	printf("(Syslog support not compiled in, using stderr)\n");
	printf("-m		Don't display the motd on login\n");
	printf("-w		Disallow root logins\n");
	printf("-G		Restrict logins to members of specified group\n");
	printf("-s		Disable password logins\n");
	printf("-g		Disable password logins for root\n");
	printf("-B		Allow blank password logins\n");
	printf("-t		Enable two-factor authentication (both password and public key required)\n");
	printf("-T		Maximum authentication tries (default 10)\n");
	printf("-j		Disable local port forwarding\n");
	printf("-k		Disable remote port forwarding\n");
	printf("-a		Allow connections to forwarded ports from any host\n");
	printf("-c command	Force executed command\n");
	printf("-p [address:]port\n");
	printf("		Listen on specified tcp port (and optionally address),\n");
	printf("		up to 10 can be specified\n");
	printf("		(default port is 22 if none specified)\n");
	printf("-P PidFile	Create pid file PidFile\n");
