	printf("-i		Start for inetd\n");
	printf("-W <receive_window_buffer> (default 24576, larger may be faster, max 10MB)\n");
	printf("-K <keepalive>  (0 is never, default 0, in seconds)\n");
	printf("-I <idle_timeout>  (0 is never, default 0, in seconds)\n");
	printf("-z    disable QoS\n");
	printf("-V    Version\n");
}

static void svr_parseopts(int argc, char **argv) {
	int i;
	for (i = 1; i < argc; i++) {
		char *arg = argv[i];
		if (arg[0] != '-' || arg[1] == '\0') {
			dropbear_exit("Invalid argument: %s", arg);
		}
		switch (arg[1]) {
		case 'b': {
			if (i+1 >= argc) dropbear_exit("Missing argument");
			svr_opts.banner_file = db_strdup(argv[++i]);
			break;
		}
		case 'r': {
			if (i+1 >= argc) dropbear_exit("Missing argument");
			svr_addhostkey_filename(argv[++i]);
			break;
		}
		case 'D': {
			if (i+1 >= argc) dropbear_exit("Missing argument");
			svr_opts.authdir = db_strdup(argv[++i]);
			break;
		}
		case 'p': {
			if (i+1 >= argc) dropbear_exit("Missing argument");
			if (nlisten >= MAX_LISTEN_PORTS) dropbear_exit("Too many listen ports");
			{
				char *addr = argv[++i];
				char *colon = strrchr(addr, ':');
				if (colon) {
					listen_addrs[nlisten][0] = db_malloc(colon-addr+1);
					memcpy(listen_addrs[nlisten][0], addr, colon-addr);
					listen_addrs[nlisten][0][colon-addr] = '\0';
					listen_addrs[nlisten][1] = db_strdup(colon+1);
				} else {
					listen_addrs[nlisten][0] = NULL;
					listen_addrs[nlisten][1] = db_strdup(addr);
				}
				nlisten++;
			}
			break;
		}
		case 'c': {
			if (i+1 >= argc) dropbear_exit("Missing argument");
			svr_opts.cmd = db_strdup(argv[++i]);
			svr_opts.forcecmd = 1;
			break;
		}
		case 'G': {
			struct group *g;
			if (i+1 >= argc) dropbear_exit("Missing argument");
			g = getgrnam(argv[++i]);
			if (g == NULL) {
				dropbear_exit("Cannot restrict logins to group '%s' as the group does not exist", argv[i]);
			}
			svr_opts.keygroup = g->gr_gid;
			break;
		}
		case 'T': {
			unsigned int val;
			if (i+1 >= argc) dropbear_exit("Missing argument");
			{
				char *end;
				errno = 0;
				val = strtoul(argv[i+1], &end, 10);
				if (errno != 0 || end == argv[i+1] || *end != '\0') {
					dropbear_exit("Bad maxauthtries '%s'", argv[i+1]);
				}
				svr_opts.maxauthtries = val;
				i++;
			}
			break;
		}
		case 'W': {
			unsigned int val;
			if (i+1 >= argc) dropbear_exit("Missing argument");
			{
				char *end;
				errno = 0;
				val = strtoul(argv[i+1], &end, 10);
				if (errno != 0 || end == argv[i+1] || *end != '\0' || val == 0 || val > 10000000) {
					dropbear_log(LOG_INFO, "Bad recv window '%s', using 24576", argv[i+1]);
					val = 24576;
				}
				svr_opts.recv_window = val;
				i++;
			}
			break;
		}
		case 'K': {
			unsigned int val;
			if (i+1 >= argc) dropbear_exit("Missing argument");
			{
				char *end;
				errno = 0;
				val = strtoul(argv[i+1], &end, 10);
				if (errno != 0 || end == argv[i+1] || *end != '\0') {
					dropbear_exit("Bad keepalive '%s'", argv[i+1]);
				}
				svr_opts.keepalive = val;
				i++;
			}
			break;
		}
		case 'I': {
			unsigned int val;
			if (i+1 >= argc) dropbear_exit("Missing argument");
			{
				char *end;
				errno = 0;
				val = strtoul(argv[i+1], &end, 10);
				if (errno != 0 || end == argv[i+1] || *end != '\0') {
					dropbear_exit("Bad idle_timeout '%s'", argv[i+1]);
				}
				svr_opts.idle_timeout = val;
				i++;
			}
			break;
		}
		case 'P': {
			if (i+1 >= argc) dropbear_exit("Missing argument");
			svr_opts.pidfile = db_strdup(argv[++i]);
			break;
		}
		case 'l': {
			if (i+1 >= argc) dropbear_exit("Missing argument");
			svr_opts.listen_interface = db_strdup(argv[++i]);
			break;
		}
		case 'F':
			svr_opts.foreground = 1;
			break;
		case 'R':
			svr_opts.createkeys = 1;
			break;
		case 'e':
			svr_opts.passthrough_env = 1;
			break;
		case 'm':
			svr_opts.no_motd = 1;
			break;
		case 'w':
			svr_opts.norootlogin = 1;
			break;
		case 's':
			svr_opts.disable_password = 1;
			break;
		case 'g':
			svr_opts.disable_password_root = 1;
			break;
		case 'B':
			svr_opts.allow_blankpass = 1;
			break;
		case 't':
			svr_opts.twofactor = 1;
			break;
		case 'j':
			svr_opts.no_localfwd = 1;
			break;
		case 'k':
			svr_opts.no_remotefwd = 1;
			break;
		case 'a':
			svr_opts.allowfwdany = 1;
			break;
		case 'i':
			svr_opts.inetd = 1;
			break;
		case 'z':
			svr_opts.noqos = 1;
			break;
		case 'V':
			printf("Dropbear v%s\n", DROPBEAR_VERSION);
			exit(0);
		case 'h':
			usage();
			exit(1);
		default:
			printf("Invalid option -%c\n", arg[1]);
			usage();
			exit(1);
		}
	}
}
EOF
