				char *addr = argv[++i];
				char *colon = strrchr(addr, ':');
				if (colon) {
					listen_addrs[nlisten][0] = db_malloc(colon-addr+1);
					memcpy(listen_addrs[nlisten][0], addr, colon-addr);
					listen_addrs[nlisten][0][colon-addr] = '\0';
					listen_addrs[nlisten][1] = db_strdup(colon+1);
				} else {
					listen_addrs[nlisten][0] = NULL;
					listen_addrs[nlisten][1] = db_strdup(addr);
				}
				nlisten++;
			}
			break;
		}
		case 'c': {
			if (i+1 >= argc) dropbear_exit("Missing argument");
			svr_opts.cmd = db_strdup(argv[++i]);
			svr_opts.forcecmd = 1;
			break;
		}
		case 'G': {
			struct group *g;
			if (i+1 >= argc) dropbear_exit("Missing argument");
			g = getgrnam(argv[++i]);
			if (g == NULL) {
				dropbear_exit("Cannot restrict logins to group '%s' as the group does not exist", argv[i]);
			}
