/* ------------------------------------------------------------------ */
/* hostkeys                                                            */
/* ------------------------------------------------------------------ */
static int nhostkeyfilenames = 0;

void svr_addhostkey_filename(const char *filename) {
	int i;
	if (nhostkeyfilenames >= DROPBEAR_MAX_SIGN_ALGOS) return;
	/* check for duplicates */
	for (i = 0; i < nhostkeyfilenames; i++) {
		if (strcmp(svr_hostkey_filenames[i], filename) == 0) return;
	}
	svr_hostkey_filenames[nhostkeyfilenames++] = db_strdup(filename);
}

int svr_hostkey_algo_from_type(int type) { return type; }

static void loadhostkey(const char *filename, int create) {
	sign_key *key;
	int type;
	/* determine the type from the file contents */
	key = signkey_new();
	{
		int ret = signkey_load_private_file(filename, key);
		if (ret == 0) {
			type = key->type;
			if (type >= 0 && type < DROPBEAR_MAX_SIGN_ALGOS) {
				if (svr_hostkeys[type] != NULL) {
					signkey_free(key);
				} else {
					svr_hostkeys[type] = key;
				}
			} else {
				signkey_free(key);
			}
		} else {
			signkey_free(key);
			if (ret == -2) {
				/* file not found */
				if (create) {
					/* will be created on demand */
				} else {
					dropbear_log(LOG_ERR, "Failed loading %s", filename);
				}
			} else {
				dropbear_log(LOG_ERR, "Failed loading %s", filename);
			}
		}
	}
}

void svr_loadhostkeys(void) {
	int i;
	int n = nhostkeyfilenames;
	if (n == 0) {
		/* use the defaults */
		loadhostkey(DEFAULT_RSA_KEY, svr_opts.createkeys);
		loadhostkey(DEFAULT_ECDSA_KEY, svr_opts.createkeys);
		loadhostkey(DEFAULT_ED25519_KEY, svr_opts.createkeys);
	} else {
		for (i = 0; i < n; i++) {
			loadhostkey(svr_hostkey_filenames[i], svr_opts.createkeys);
		}
	}
}

static int count_hostkeys(void) {
	int i, n = 0;
	for (i = 0; i < DROPBEAR_MAX_SIGN_ALGOS; i++) if (svr_hostkeys[i]) n++;
	return n;
}

/* ------------------------------------------------------------------ */
/* listening                                                           */
/* ------------------------------------------------------------------ */
static void setlisten(int *socks, int *nsocks) {
	int i;
	for (i = 0; i < nlisten; i++) {
		char *addr = listen_addrs[i][0];
		char *port = listen_addrs[i][1];
		struct addrinfo hints, *res, *ai;
		int ret;
		memset(&hints, 0, sizeof(hints));
		hints.ai_family = AF_UNSPEC;
		hints.ai_socktype = SOCK_STREAM;
		hints.ai_flags = AI_PASSIVE;
		if (addr && addr[0] == '\0') addr = NULL;
		ret = getaddrinfo(addr, port, &hints, &res);
		if (ret != 0) {
			dropbear_log(LOG_ERR, "Failed listening on '%s': Error resolving: %s",
				listen_addrs[i][0] ? listen_addrs[i][0] : "", gai_strerror(ret));
			continue;
		}
		for (ai = res; ai != NULL; ai = ai->ai_next) {
			int sock;
			int val = 1;
			sock = socket(ai->ai_family, ai->ai_socktype, ai->ai_protocol);
			if (sock < 0) continue;
			setsockopt(sock, SOL_SOCKET, SO_REUSEADDR, &val, sizeof(val));
			if (bind(sock, ai->ai_addr, ai->ai_addrlen) != 0) {
				dropbear_log(LOG_ERR, "Failed listening on '%s': Error listening: %s",
					listen_addrs[i][0] ? listen_addrs[i][0] : "", strerror(errno));
				close(sock);
				continue;
			}
			if (listen(sock, 20) != 0) {
				dropbear_log(LOG_ERR, "Failed listening on '%s': Error listening: %s",
					listen_addrs[i][0] ? listen_addrs[i][0] : "", strerror(errno));
				close(sock);
				continue;
			}
			if (svr_opts.listen_interface) {
				dropbear_log(LOG_INFO, "Binding to interface '%s'", svr_opts.listen_interface);
				if (setsockopt(sock, SOL_SOCKET, SO_BINDTODEVICE, svr_opts.listen_interface,
							strlen(svr_opts.listen_interface)+1) != 0) {
					dropbear_log(LOG_ERR, "Couldn't set SO_BINDTODEVICE");
				}
			}
			socks[(*nsocks)++] = sock;
			dropbear_set_nonblocking(sock);
		}
		freeaddrinfo(res);
	}
}

/* ------------------------------------------------------------------ */
/* accept loop                                                         */
/* ------------------------------------------------------------------ */
static void connection_child(int fd, int inetd) {
	struct sockaddr_storage sa;
	socklen_t salen = sizeof(sa);
	char ipaddr[128];
	ses.sock = fd;
	ses.is_inetd = inetd;
	ipaddr[0] = '\0';
	if (!inetd) {
		if (getpeername(fd, (struct sockaddr*)&sa, &salen) == 0) {
			char portstr[16];
			if (sa.ss_family == AF_INET) {
				struct sockaddr_in *in4 = (struct sockaddr_in*)&sa;
				inet_ntop(AF_INET, &in4->sin_addr, ipaddr, sizeof(ipaddr));
				snprintf(portstr, sizeof(portstr), "%u", ntohs(in4->sin_port));
			} else if (sa.ss_family == AF_INET6) {
				struct sockaddr_in6 *in6 = (struct sockaddr_in6*)&sa;
				inet_ntop(AF_INET6, &in6->sin6_addr, ipaddr, sizeof(ipaddr));
				snprintf(portstr, sizeof(portstr), "%u", ntohs(in6->sin6_port));
			} else {
				strlcpy(portstr, "0", sizeof(portstr));
			}
			strlcpy(ses.addrstring, ipaddr, sizeof(ses.addrstring));
			strlcat(ses.addrstring, ":");
			strlcat(ses.addrstring, portstr);
			ses.remote_port = atoi(portstr);
		}
	} else {
		if (getpeername(0, (struct sockaddr*)&sa, &salen) == 0) {
			char portstr[16];
			if (sa.ss_family == AF_INET) {
				struct sockaddr_in *in4 = (struct sockaddr_in*)&sa;
				inet_ntop(AF_INET, &in4->sin_addr, ipaddr, sizeof(ipaddr));
				snprintf(portstr, sizeof(portstr), "%u", ntohs(in4->sin_port));
				strlcpy(ses.addrstring, ipaddr, sizeof(ses.addrstring));
				strlcat(ses.addrstring, ":");
				strlcat(ses.addrstring, portstr);
				ses.remote_port = atoi(portstr);
			}
		}
	}
	dropbear_log(LOG_INFO, "Child connection from %s", ses.addrstring);
	/* close the listening sockets */
	{
		int i;
		for (i = 0; i < nlisten_socks; i++) close(listen_socks[i]);
	}
	svr_loadhostkeys_runtime();
	session_main();
	exit(0);
}

/* fill in ses options from svr_opts */
static void ses_setup(void) {
	ses.maxauthtries = svr_opts.maxauthtries;
	ses.norootlogin = svr_opts.norootlogin;
	ses.disable_password = svr_opts.disable_password;
	ses.allow_blankpass = svr_opts.allow_blankpass;
	ses.twofactor = svr_opts.twofactor;
	ses.no_localfwd = svr_opts.no_localfwd;
	ses.no_remotefwd = svr_opts.no_remotefwd;
	ses.allowfwdany = svr_opts.allowfwdany;
	ses.forcecmd = svr_opts.forcecmd;
	ses.cmd = svr_opts.cmd;
	ses.passthrough_env = svr_opts.passthrough_env;
	ses.no_motd = svr_opts.no_motd;
	ses.recv_window = svr_opts.recv_window;
	ses.banner_file = svr_opts.banner_file;
	ses.authdir = svr_opts.authdir;
	ses.keygroup = svr_opts.keygroup;
}

int main(int argc, char **argv) {
	progname = argv[0];
	crypto_init();
	memset(&svr_opts, 0, sizeof(svr_opts));
	svr_opts.recv_window = 24576;
	svr_opts.maxauthtries = 10;
	svr_opts.idle_timeout = 0;
	svr_opts.keepalive = 0;
	memset(&ses, 0, sizeof(ses));
	ses.sock = -1;
	chansession_init();
	memset(svr_hostkeys, 0, sizeof(svr_hostkeys));

	svr_parseopts(argc, argv);
	/* options that need the child setup */
	ses.maxauthtries = svr_opts.maxauthtries;
	ses.recv_window = svr_opts.recv_window;
	ses.no_localfwd = svr_opts.no_localfwd;
	ses.no_remotefwd = svr_opts.no_remotefwd;
	ses.disable_password = svr_opts.disable_password;
	ses.norootlogin = svr_opts.norootlogin;
	ses.allow_blankpass = svr_opts.allow_blankpass;
	ses.twofactor = svr_opts.twofactor;
	ses.forcecmd = svr_opts.forcecmd;
	ses.cmd = svr_opts.cmd;
	ses.passthrough_env = svr_opts.passthrough_env;
	ses.no_motd = svr_opts.no_motd;
	ses.banner_file = svr_opts.banner_file;
	ses.authdir = svr_opts.authdir;
	ses.keygroup = svr_opts.keygroup;
	ses.allowfwdany = svr_opts.allowfwdany;

	if (svr_opts.inetd) {
		connection_child(0, 1);
		return 0;
	}

	/* listening sockets */
	listen_socks = db_malloc(sizeof(int) * MAX_LISTEN_PORTS * 4);
	if (nlisten == 0) {
		listen_addrs[0][0] = NULL;
		listen_addrs[0][1] = db_strdup("22");
		nlisten = 1;
	}
	setlisten(listen_socks, &nlisten_socks);
	if (nlisten_socks == 0) {
		dropbear_exit("No listening ports available.");
	}

	svr_loadhostkeys();
	if (!svr_opts.createkeys && count_hostkeys() == 0) {
		dropbear_exit("No hostkeys available. 'dropbear -R' may be useful or run dropbearkey.");
	}

	if (!svr_opts.foreground) {
		pid_t pid = fork();
		if (pid < 0) {
			dropbear_exit("Failed to fork");
		}
		if (pid > 0) {
			_exit(0);
		}
		setsid();
		if (svr_opts.pidfile) {
			FILE *f = fopen(svr_opts.pidfile, "w");
			if (f) {
				fprintf(f, "%d\n", getpid());
				fclose(f);
			}
		}
		dropbear_log(LOG_INFO, "Running in background");
	} else {
		dropbear_log(LOG_INFO, "Not backgrounding");
		if (svr_opts.pidfile) {
			FILE *f = fopen(svr_opts.pidfile, "w");
			if (f) {
				fprintf(f, "%d\n", getpid());
				fclose(f);
			}
		}
	}

	{
		int i;
		for (i = 0; i < nlisten_socks; i++) dropbear_set_nonblocking(listen_socks[i]);
	}

	while (1) {
		fd_set rset;
		int maxfd = -1;
		int i;
		int ret;
		FD_ZERO(&rset);
		for (i = 0; i < nlisten_socks; i++) {
			FD_SET(listen_socks[i], &rset);
			if (listen_socks[i] > maxfd) maxfd = listen_socks[i];
		}
		ret = select(maxfd+1, &rset, NULL, NULL, NULL);
		if (ret < 0) {
			if (errno == EINTR) continue;
			dropbear_exit("select failed");
		}
		for (i = 0; i < nlisten_socks; i++) {
			if (FD_ISSET(listen_socks[i], &rset)) {
				struct sockaddr_storage sa;
				socklen_t salen = sizeof(sa);
				int fd = accept(listen_socks[i], (struct sockaddr*)&sa, &salen);
				if (fd < 0) continue;
				{
					pid_t pid = fork();
					if (pid == 0) {
						/* child */
						int j;
						for (j = 0; j < nlisten_socks; j++) close(listen_socks[j]);
						db_free(listen_socks);
						connection_child(fd, 0);
						exit(0);
					}
					close(fd);
				}
			}
		}
	}
	return 0;
}
