	ses.sock = fd;
	ses.is_inetd = inetd;
	ipaddr[0] = '\0';
	if (!inetd) {
		if (getpeername(fd, (struct sockaddr*)&sa, &salen) == 0) {
			char portstr[16];
			if (sa.ss_family == AF_INET) {
				struct sockaddr_in *in4 = (struct sockaddr_in*)&sa;
				inet_ntop(AF_INET, &in4->sin_addr, ipaddr, sizeof(ipaddr));
				snprintf(portstr, sizeof(portstr), "%u", ntohs(in4->sin_port));
			} else if (sa.ss_family == AF_INET6) {
				struct sockaddr_in6 *in6 = (struct sockaddr_in6*)&sa;
				inet_ntop(AF_INET6, &in6->sin6_addr, ipaddr, sizeof(ipaddr));
				snprintf(portstr, sizeof(portstr), "%u", ntohs(in6->sin6_port));
			} else {
				strlcpy(portstr, "0", sizeof(portstr));
			}
			strlcpy(ses.addrstring, ipaddr, sizeof(ses.addrstring));
			strlcat(ses.addrstring, ":");
			strlcat(ses.addrstring, portstr);
			ses.remote_port = atoi(portstr);
		}
	} else {
		if (getpeername(0, (struct sockaddr*)&sa, &salen) == 0) {
			char portstr[16];
			if (sa.ss_family == AF_INET) {
				struct sockaddr_in *in4 = (struct sockaddr_in*)&sa;
				inet_ntop(AF_INET, &in4->sin_addr, ipaddr, sizeof(ipaddr));
				snprintf(portstr, sizeof(portstr), "%u", ntohs(in4->sin_port));
				strlcpy(ses.addrstring, ipaddr, sizeof(ses.addrstring));
				strlcat(ses.addrstring, ":");
				strlcat(ses.addrstring, portstr);
				ses.remote_port = atoi(portstr);
			}
		}
	}
	dropbear_log(LOG_INFO, "Child connection from %s", ses.addrstring);
	/* close the listening sockets */
	{
		int i;
		for (i = 0; i < nlisten_socks; i++) close(listen_socks[i]);
	}
	svr_loadhostkeys_runtime();
	session_main();
	exit(0);
}

