	ses.maxauthtries = svr_opts.maxauthtries;
	ses.norootlogin = svr_opts.norootlogin;
	ses.disable_password = svr_opts.disable_password;
	ses.allow_blankpass = svr_opts.allow_blankpass;
	ses.twofactor = svr_opts.twofactor;
	ses.no_localfwd = svr_opts.no_localfwd;
	ses.no_remotefwd = svr_opts.no_remotefwd;
	ses.allowfwdany = svr_opts.allowfwdany;
	ses.forcecmd = svr_opts.forcecmd;
	ses.cmd = svr_opts.cmd;
	ses.passthrough_env = svr_opts.passthrough_env;
	ses.no_motd = svr_opts.no_motd;
	ses.recv_window = svr_opts.recv_window;
	ses.banner_file = svr_opts.banner_file;
	ses.authdir = svr_opts.authdir;
	ses.keygroup = svr_opts.keygroup;
}

int main(int argc, char **argv) {
	progname = argv[0];
	crypto_init();
	memset(&svr_opts, 0, sizeof(svr_opts));
	svr_opts.recv_window = 24576;
	svr_opts.maxauthtries = 10;
	svr_opts.idle_timeout = 0;
	svr_opts.keepalive = 0;
	memset(&ses, 0, sizeof(ses));
	ses.sock = -1;
	chansession_init();
	memset(svr_hostkeys, 0, sizeof(svr_hostkeys));

	svr_parseopts(argc, argv);
	/* options that need the child setup */
	ses.maxauthtries = svr_opts.maxauthtries;
	ses.recv_window = svr_opts.recv_window;
	ses.no_localfwd = svr_opts.no_localfwd;
	ses.no_remotefwd = svr_opts.no_remotefwd;
	ses.disable_password = svr_opts.disable_password;
	ses.norootlogin = svr_opts.norootlogin;
	ses.allow_blankpass = svr_opts.allow_blankpass;
	ses.twofactor = svr_opts.twofactor;
	ses.forcecmd = svr_opts.forcecmd;
	ses.cmd = svr_opts.cmd;
	ses.passthrough_env = svr_opts.passthrough_env;
	ses.no_motd = svr_opts.no_motd;
	ses.banner_file = svr_opts.banner_file;
	ses.authdir = svr_opts.authdir;
	ses.keygroup = svr_opts.keygroup;
	ses.allowfwdany = svr_opts.allowfwdany;

	if (svr_opts.inetd) {
		connection_child(0, 1);
		return 0;
	}

	/* listening sockets */
	listen_socks = db_malloc(sizeof(int) * MAX_LISTEN_PORTS * 4);
	if (nlisten == 0) {
		listen_addrs[0][0] = NULL;
		listen_addrs[0][1] = db_strdup("22");
		nlisten = 1;
	}
	setlisten(listen_socks, &nlisten_socks);
	if (nlisten_socks == 0) {
		dropbear_exit("No listening ports available.");
	}

	svr_loadhostkeys();
	if (!svr_opts.createkeys && count_hostkeys() == 0) {
		dropbear_exit("No hostkeys available. 'dropbear -R' may be useful or run dropbearkey.");
	}

	if (!svr_opts.foreground) {
		pid_t pid = fork();
		if (pid < 0) {
			dropbear_exit("Failed to fork");
		}
		if (pid > 0) {
			_exit(0);
		}
		setsid();
		if (svr_opts.pidfile) {
			FILE *f = fopen(svr_opts.pidfile, "w");
			if (f) {
				fprintf(f, "%d\n", getpid());
				fclose(f);
			}
		}
		dropbear_log(LOG_INFO, "Running in background");
	} else {
		dropbear_log(LOG_INFO, "Not backgrounding");
		if (svr_opts.pidfile) {
			FILE *f = fopen(svr_opts.pidfile, "w");
			if (f) {
				fprintf(f, "%d\n", getpid());
				fclose(f);
			}
		}
	}

	{
		int i;
		for (i = 0; i < nlisten_socks; i++) dropbear_set_nonblocking(listen_socks[i]);
	}

	while (1) {
		fd_set rset;
		int maxfd = -1;
		int i;
		int ret;
		FD_ZERO(&rset);
		for (i = 0; i < nlisten_socks; i++) {
			FD_SET(listen_socks[i], &rset);
			if (listen_socks[i] > maxfd) maxfd = listen_socks[i];
		}
		ret = select(maxfd+1, &rset, NULL, NULL, NULL);
		if (ret < 0) {
			if (errno == EINTR) continue;
			dropbear_exit("select failed");
		}
		for (i = 0; i < nlisten_socks; i++) {
			if (FD_ISSET(listen_socks[i], &rset)) {
				struct sockaddr_storage sa;
				socklen_t salen = sizeof(sa);
				int fd = accept(listen_socks[i], (struct sockaddr*)&sa, &salen);
				if (fd < 0) continue;
				{
					pid_t pid = fork();
					if (pid == 0) {
						/* child */
						int j;
						for (j = 0; j < nlisten_socks; j++) close(listen_socks[j]);
						db_free(listen_socks);
						connection_child(fd, 0);
						exit(0);
					}
					close(fd);
				}
			}
		}
	}
	return 0;
}
