/* negotiate the host key algorithm against the keys we have (or can create) */
int svr_hostkey_negotiate(const char *client_list) {
	int avail[DROPBEAR_MAX_SIGN_ALGOS];
	const char *p = client_list;
	int i;
	for (i = 0; i < DROPBEAR_MAX_SIGN_ALGOS; i++) {
		avail[i] = (svr_hostkeys[i] != NULL) || svr_opts.createkeys;
	}
	while (*p) {
		const char *end = strchr(p, ',');
		size_t len = end ? (size_t)(end - p) : strlen(p);
		const algo_type *a;
		char *tmp;
		if (len == 0) {
			if (!end) break;
			p = end + 1;
			continue;
		}
		tmp = db_malloc(len+1);
		memcpy(tmp, p, len);
		tmp[len] = '\0';
		for (a = sshhostkey_algos; a->name != NULL; a++) {
			if (strcmp(a->name, tmp) == 0 && avail[a->val]) {
				db_free(tmp);
				return a->val;
			}
		}
		db_free(tmp);
		if (!end) break;
		p = end + 1;
	}
	return -1;
}
