{"command": "cat > /tmp/tsign.c <<'EOF'
#include "dropbear.h"
#include <stdio.h>
int main(int argc, char**argv) {
	sign_key *key = signkey_new();
	int ret = signkey_load_private_file(argv[1], key);
	printf("load ret %d type %d\n", ret, key->type);
	if (ret == 0) {
		buffer *sig = buf_new(1024);
		unsigned char data[32];
		int i;
		for (i=0;i<32;i++) data[i]=i;
		ret = signkey_sign(key, data, 32, 0, sig);
		printf("sign ret %d siglen %u\n", ret, sig->len);
		/* write the signature for openssl verification */
		{
			unsigned int l;
			FILE*f;
			l = buf_getint(sig); printf("alg len %u\n", l);
			/* skip algname */
			buf_incrpos(sig, l);
			l = buf_getint(sig);
			f=fopen("/tmp/tsig.bin","wb"); fwrite(sig->data+sig->pos,1,l,f); fclose(f);
			printf("sigbytes %u\n", l);
		}
		/* also write the public key */
		{
			buffer *pub = buf_new(1024);
			signkey_write_pub_key(key, pub);
			f=fopen("/tmp/tpub.bin","wb"); fwrite(pub->data,1,pub->len,f); fclose(f);
			printf("publen %u\n", pub->len);
			/* verify with openssl */
			char cmd[512];
			snprintf(cmd,sizeof(cmd),"openssl pkeyutl -verify -pubin -inkey /tmp/tpempub.pem -sigfile /tmp/tsig.bin -in /tmp/thash.bin 2>&1");
			f=fopen("/tmp/tpempub.pem","w"); 
			{
				const RSA *rsa = EVP_PKEY_get0_RSA(key->rsa);
				const BIGNUM *n,*e,*d;
				RSA_get0_key(rsa,&n,&e,&d);
				PEM_write_RSAPublicKey(f, (RSA*)rsa);
			}
			fclose(f);
			f=fopen("/tmp/thash.bin","wb"); fwrite(data,1,32,f); fclose(f);
			printf("%s\n", (char*)popen(cmd,"r")? "" : "");
			system(cmd);
		}
	}
	return 0;
}
EOF
