import struct,hashlib,json,itertools
d=json.load(open('/tmp/kexdata.json'))
S=lambda b: struct.pack('>I',len(b))+b
ver_c=d['ver_c'].encode(); ver_s=d['ver_s'].encode()
ic_f=bytes.fromhex(d['ic_full']); ic_n=bytes.fromhex(d['ic_notype'])
is_f=bytes.fromhex(d['is_full']); is_n=bytes.fromhex(d['is_notype'])
ks=bytes.fromhex(d['ks']); e=bytes.fromhex(d['e']); f=bytes.fromhex(d['f']); k=bytes.fromhex(d['k'])
target=bytes.fromhex('34352828c2efee5cef0896646824943c924b694037308fba9c4198a038157bd3')
def H(parts):
    h=hashlib.sha256()
    for p in parts: h.update(p)
    return h.digest()
# 8 fields: ver_c, ver_s, ic, is, ks, e, f, k ; each can be string-prefixed or raw; ic/is can be full or notype
found=[]
for ic in (ic_f, ic_n):
  for isx in (is_f, is_n):
    fields=[ver_c, ver_s, ic, isx, ks, e, f, k]
    for mask in itertools.product([0,1],repeat=8):
        parts=[S(x) if m else x for x,m in zip(fields,mask)]
        v=H(parts)
        if v==target: found.append((ic is ic_f, isx is is_f, mask))
print('found:',found)
PY"}

