		unsigned char *polykey, unsigned char *lenbuf, const unsigned char *lendata,
		unsigned char *databuf, const unsigned char *data, unsigned int datalen);
int main(){
	unsigned char key[32]; unsigned int i;
	for (i=0;i<32;i++) key[i]=i;
	unsigned char polykey[32], lenbuf[4], data[64];
	unsigned char lendata[4]={0,0,0,32};
	unsigned char databuf[64];
